comms.text:
@1 וְאִתְגְּלִי לֵהּ יְיָ בְּמֵישְׁרֵי מַמְרֵא וְהוּא יָתֵב בִּתְרַע מַשְׁכְּנָא כְּמֵיחַם יוֹמָא:
@2 וּזְקַף עֵינוֹהִי וַחֲזָא וְהָא תְּלָתָא גֻּבְרִין (נ''י גַּבְרִין) קָיְמִין עִלָּווֹהִי וַחֲזָא וּרְהַט לְקַדָּמוּתְהוֹן מִתְּרַע מַשְׁכְּנָא וּסְגִיד עַל אַרְעָא:
@3 וַאֲמָר יְיָ אִם כְּעַן אַשְׁכָּחִית רַחֲמִין קֳדָמָךְ (נ''י בְּעֵינָיךְ) לָא כְעַן תְּעִבַּר מֵעַל עַבְדָּךְ:
@4 יִסְּבוּן כְּעַן זְעֵיר מַיָּא וְאַסְחוּ רַגְלֵיכוֹן וְאִסְתְּמִיכוּ תְּחוֹת אִילָנָא:
@5 וְאֶסַּב פִּתָּא דְלַחְמָא וּסְעִידוּ לִבְּכוֹן בָּתַר כֵּן תְּעִבְּרוּן אֲרֵי עַל כֵּן עֲבַרְתּוּן עַל עַבְדְּכוֹן וַאֲמָרוּ כֵּן תַּעְבֵּיד כְּמָא דִּי מַלֵּלְתָּא:
@6 וְאוֹחִי אַבְרָהָם לְמַשְׁכְּנָא לְוַת שָׂרָה וַאֲמַר אוֹחָא תְּלָת סְאִין קִמְחָא דְּסָלְתָּא לוּשִׁי וְעִבִידִי גְּרִיצָן:
@7 וּלְוַת תּוֹרֵי רְהַט אַבְרָהָם וּדְבַר בַּר תּוֹרֵי רַכִּיךְ וְטַב וִיהַב לְעוּלֵמָא וְאוֹחִי לְמֶעְבַּד יָתֵהּ:
@8 וּנְסִיב שְׁמַן וַחֲלָב וּבַר תּוֹרֵי דִּי עֲבַד וִיהַב קֳדָמֵיהוֹן וְהוּא מְשַׁמֵּשׁ עִלָּוֵיהוֹן תְּחוֹת אִילָנָא וַאֲכָלוּ:
@9 וַאֲמָרוּ לֵהּ אָן שָׂרָה אִתְּתָךְ וַאֲמַר הָא בְמַשְׁכְּנָא:
@10 וַאֲמַר מִתַּב אִתּוּב לְוָתָךְ כְּעִדָּן דְּאַתּוּן קַיָּמִין וְהָא בַר לְשָׂרָה אִתְּתָךְ וְשָׂרָה שְמַעַת בִּתְרַע מַשְׁכְנָא וְהוּא אֲחוֹרוֹהִי:
@11 וְאַבְרָהָם וְשָׂרָה סִיבוּ עַלּוּ בְיוֹמִין פְּטַק מִלְּמֶהֱוֵי לְשָׂרָה אוֹרַח כִּנְשַׁיָּא:
@12 וְחַיְכַת שָׂרָה בִּטְעָהַהּ לְמֵימָר בָּתַר דְּסֵיבִית הֲוַת לִי עוּלֵימוּ וְרִבּוֹנִי םִיב:
@13 וַאֲמַר יְיָ לְאַבְרָהָם לְמָּא דְנָן חַיְכַת שָׂרָה לְמֵימַר הַבְרַם בְּקוּשְׁטָא אוֹלִיד וַאֲנָא סֵיבִית:
@14 הַיִתְכַּסֵּי מִן קֳדָם יְיָ פִּתְגָּמָא לִזְמַן אִתּוּב לְוָתָךְ כְּעִדָּן דְּאַתּוּן קַיָּמִין וּלְשָׂרָה בָר:
@15 וְכַדִּיבַת שָׂרָה לְמֵימָר לָא חַיֵּכִית אֲרֵי דְחֵלַת וַאֲמַר לָא בְּרַם חַיָּכְתְּ:
@16 וְקָמוּ מִתַּמָּן גֻּבְרַיָּא וְאִסְתְּכִיאוּ עַל אַפֵּי סְדוֹם וְאַבְרָהָם אָזַל עִמְּהוֹן לְאַלְווֹאֵיהוֹן:
@17 וַיְיָ אֲמָר הַמְכַסֵּי אֲנָא מֵאַבְרָהָם דִּי אֲנָא עָבֵד:
@18 וְאַבְרָהָם מֵהֲוָה יֶהֱוֵי לְעַם סַגִּי וְתַקִּיף וְיִתְבָּרְכוּן בְּדִילֵהּ כֹּל עַמְמֵי אַרְעָא:
@19 אֲרֵי גְּלִי קֳדָמַי (גי' רמב''ן יְדַעְתִּנֵּהּ) בְּדִיל דִּי יְפַקֵּד יָת בְּנוֹהִי וְיָת אֱנַשׁ בֵּיתֵהּ בַּתְרוֹהִי וְיִטְּרוּן אָרְחָן דְּתַקְּנָן קֳדָם יְיָ לְמֶעֱבַּד צְדַקְתָּא וְדִינָא בְּדִיל אַיְיתִי יְיָ עַל אַבְרָהָם יָת דְּמַלֵּל עֲלוֹהִי:
@20 וַאֲמַר יְיָ קְבֵלַת סְדוֹם וַעֲמוֹרָה אֲרֵי סְגִיאַת וְחוֹבָתְהוֹן אֲרֵי תְקִיפַת לַחֲדָא:
@21 אִתְגְּלֵי כְעַן וְאֶדּוּן הֲכִי קְבִלְתְּהוֹן דְּעַלַּת לָקֳדָמַי עֲבָדוּ אֶעְבֵּד עִמְּהוֹן גְּמִירָא אִם לָא תָיְבִין וְאִם תָּיְבִין לָא אֶתְפְּרָע:
@22 וְאִתְפְּנִיאוּ מִתַּמָּן גֻּבְרַיָּא וַאֲזָלוּ לִסְדוֹם וְאַבְרָהָם עַד כְּעַן מְשַׁמֵּשׁ בִּצְלוֹ קֳדָם יְיָ:
@23 וּקְרֵב אַבְרָהָם וַאֲמָר הֲבִרְגַז תְּשֵׁיצֵי זַכָּאָה עִם חַיָּבָא:
@24 מָאִים אִית חַמְּשִׁין זַכָּאִין בְּגוֹ קַרְתָּא הֲבִרְגַז תְּשֵׁיצֵי וְלָא תִשְׁבּוֹק לְאַתְרָא בְּדִיל חַמְשִׁין זַכָּאִין דִּי בְגַוָּהּ:
@25 קוּשְׁטָא אִנּוּן דִּינָךְ מִלְּמֶעְבַּד כְּפִתְגָּמָא הָדֵין לְקַטָּלָא זַכָּאָה עִם חַיָּבָא וִיהֵי זַכָּאָה כְּחַיָּבָא קוּשְׁטָא אִנּוּן דִּינָךְ דְּדָיִן כָּל אַרְעָא לָא יַעְבֵד דִּינָא:
@26 וַאֲמַר יְיָ אִם אַשְׁכַּח בִּסְדוֹם חַמְשִׁין זַכָּאִין בְּגוֹ קַרְתָּא וְאֶשְׁבּוֹק לְכָל אַתְרָא בְּדִילְהוֹן:
@27 וַאֲתֵב אַבְרָהָם וַאֲמַר הָא כְעַן שָׁרֵיתִי לְמַלָּלָא קֳדָם יְיָ וַאֲנָא עָפָר וּקְטָם:
@28 מָאִים יַחְסְרוּן חַמְשִׁין זַכָּאִין חַמְשָׁא הַתְחַבֵּל בְּחַמְשָׁא יָת כָּל קַרְתָּא וַאֲמַר לָא אֲחַבֵּל אִם אַשְׁכַּח תַּמָּן אַרְבְּעִין וְחַמְשָׁא:
@29 וְאוֹסִף עוֹד לְמַלָּלָא קֳדָמוֹהִי וַאֲמַר מָאִים יִשְׁתַּכְחוּן תַּמָּן אַרְבְּעִין וַאֲמַר לָא אֶעְבְּד גְּמֵרָא בְּדִיל אַרְבְּעִין:
@30 וַאֲמַר לָא כְעַן יִתְקֵף קֳדָם יְיָ (נ''י רוּגְזָא דַּיְיָ) וַאֲמַלֵּל מָאִים יִשְׁתַּכְּחוּן תַּמָּן תְּלָתִין וַאֲמַר לָא אֶעְבֵּד גְּמֵרָא אִם אַשְׁכַּח תַּמָּן תְּלָתִין:
@31 וַאֲמַר הָא כְעַן שָׁרֵיתִי לְמַלָּלָא קֳדָם יְיָ מָאִים יִשְׁתַּכְּחוּן תַּמָּן עֶשְרִין וַאֲמַר לָא אֲחַבֵּל בְּדִיל עֶשְׁרִין:
@32 וַאֲמַר לָא כְעַן יִתְקֵף קֳדָם יְיָ (נ''י רוּגְזָא דַּיְיָ) וֶאֱמַלֵּל בְּרַם זִמְנָא הָדָא מָאִים יִשְׁתַּכְּחוּן תַּמָּן עַשְׂרָא וַאֲמַר לָא אֲחַבֵּל בְּדִיל עַשְׂרָא:
@33 וְאִסְתַּלַּק יְקָרָא דַּיְיָ כַּד שֵׁצִי לְמַלָּלָא עִם אַבְרָהָם וְאַבְרָהָם תָּב לְאַתְרֵהּ:
@34 וְעַלּוּ תְּרֵין מַלְאָכַיָּא לִסְדוֹם בְּרַמְשָׁא וְלוֹט יָתֵב בְּתַרְעָא (נ''י בִּתְרַע) דִּסְדוֹם וַחֲזָא לוֹט וְקָם לְקַדָּמוּתְהוֹן וּסְגִיד עַל אַפּוֹהִי עַל אַרְעָא:
@35 וַאֲמַר בְּבָעוּ כְעַן רִבּוֹנַי זוּרוּ כְעַן לְבֵית עַבְדְּכוֹן וּבִיתוּ וְאַסְחוּ רַגְלֵיכוֹן וּתְקַדְּמוּן וּתְהָכוּן לְאָרְחֲכוֹן וְאֲמָרוּ לָא אֶלָּהֵן בִּרְחוֹבָא נְבִית:
@36 וְאַתְקַף בְּהוֹן לַחֲדָא וְזָרוּ לְוָתֵהּ וְעַלּוּ לְבֵיתֵהּ וַעֲבַד לְהוֹן מִשְׁתְּיָא וּפַטִּיר אֲפָא לְהוֹן וְאֲכָלוּ:
@37 עַד לָא שְׁכִיבוּ וְאֲנָשֵׁי קַרְתָּא אֲנָשֵׁי סְדוֹם אַקִּיפוּ עַל בֵּיתָא מֵעוּלֵימָא וְעַד סָבָא כָּל עַמָּא מִסּוֹפֵהּ:
@38 וּקְרוֹ לְלוֹט וַאֲמָרוּ לֵהּ אָן גֻּבְרַיָא דִּי אֲתוֹ לְוָתָךְ לֵילְיָא אַפֵּקִנּוּן לְוָתָנָא וְנִדַּע יָתְהוֹן:
@39 וּנְפַק לְוָתְהוֹן לוֹט לְתַרְעָא וְדָשָׁא אֲחַד בַּתְרוֹהִי:
@40 וַאֲמַר בְּבָעוּ כְעַן אַחַי לָא תַבְאִישוּן:
@41 הָא כְעַן לִי תַּרְתֵּין בְּנָן דִּי לָא יְדָעִנּוּן גְּבַר אַפֵּק כְּעַן יַתְהוֹן לְוָתְכוֹן וְעִיבִידוּ לְהֵן כִּדְתַקֵּן בְּעֵינֵיכוֹן לְחוֹד לְגֻבְרַיָּא הָאִלֵּין לָא תַעְבְּדוּן מִדַּעַם אֲרֵי עַל כֵּן עַלּוּ בִּטְלַל שֵׁרוּתִי:
@42 וַאֲמָרוּ קְרֵב לְהַלָּא וַאֲמָרוּ חַד אֲתָא לְאִתּוֹתָבָא והָא דָיִין דִּינָא כְּעַן נַבְאֵשׁ לָךְ מִדִּילְהוֹן וּתְקִיפוּ בְגַבְרָא בְלוֹט לַחֲדָא וּקְרִיבוּ לְמִתְּבַר דָּשָׁא:
@43 וְאוֹשִׁיטוּ גֻּבְרַיָּא יָת יְדֵיהוֹן וְאַיְתִיאוּ יָת לוֹט לְוָתְהוֹן לְבֵיתָא וְיָת דָּשָׁא אֲחָדוּ:
@44 וְיָת גֻּבְרַיָּא דִּי בִתְרַע בֵּיתָא מְחוֹ בְּשַׁבְרִירַיָּא מִזְּעֵירָא וְעַד רַבָּא וּלְאִיוּ לְאַשְׁכָּחָא תַרְעָא:
@45 וַאֲמָרוּ גֻּבְרַיָּא לְלוֹט עוֹד מָן לָךְ הָכָא חַתְנָא וּבְנָךְ וּבְנָתָךְ וְכֹל דִּי לָךְ בְּקַרְתָּא אַפֵּיק מִן אַתְרָא:
@46 אֲרֵי מְחַבְּלִין אֲנַחְנָא יָת אַתְרָא הָדֵין אֲרֵי סְגִיאַת קְבִלְתְּהוֹן קֳדָם יְיָ וְשַׁלְּחָנָא יְיָ לְחַבָּלוּתַהּ:
@47 וּנְפַק לוֹט וּמַלֵּיל עִם חַתְנוֹהִי נָסְבֵי בְנָתֵהּ וְאֲמַר קוּמוּ פּוּקוּ מִן אַתְרָא הָדֵין אֲרֵי מְחַבֵּל יְיָ יָת קַרְתָּא וַהֲוָה כִּמְחָיִךְ בְּעֵינֵי חַתְנוֹהִי:
@48 וּכְמִסַּק צַפְרָא הֲוָה וּדְחִיקוּ מַלְאָכַיָּא בְּלוֹט לְמֵימָר קוּם דְּבַר יָת אִתְּתָךְ וְיָת תַּרְתֵּין בְּנָתָךְ דְּאִשְׁתְּכַחַן מְהֵימְנָא עִמָּךְ דִּילְמָא תִלְקֵי בְּחוֹבֵי קַרְתָּא:
@49 וְאִתְעַכַּב וְאַתְקִיפוּ גֻּבְרַיָּא בִּידֵהּ וּבִידָא דְּאִתְּתֵהּ וּבִידָא דְתַּרְתֵּין בְּנָתֵהּ כִּרְחַם (נ''י כַּד חָס) יְיָ עֲלוֹהִי וְאַפְּקוּהִי וְאַשְׁרוּהי מִבָּרָא לְקַרְתָּא:
@50 וַהֲוָה כַּד אַפִּיקוּ יָתְהוֹן לְבָרָא וַאֲמַר חוּס עַל נַפְשָׁךְ לָא תִּסְתְּכִי לַאֲחוֹרָךְ וְלָא תְקוּם בְּכָל מֵישְׁרָא לְטוּרָא אִשְׁתְּזֵב דִּלְמָא תִלְקֵי:
@51 וַאֲמַר לוֹט לְהוֹן בְּבָעוּ כְעַן רִבּוֹנָי (נ''י יְיָ):
@52 הָא כְעַן אַשְׁכַּח עַבְדָךְ רַחֲמִין קֳדָמָךְ וְאַסְגֵּיתָא טֵיבוּתָךְ דִּי עֲבַדְתָּ עִמִּי לְקַיָּמָא יָת נַפְשִׁי וַאֲנָא לֵית אֲנָא יָכִיל לְאִשְׁתֵּזָבָא לְטּוּרָא דִּילְמָא תְעַרְעִנַּנִי בִשְׁתָּא וְאֵימוּת:
@53 הָא כְעַן קַרְתָּא הָדָא קְרִיבָא לְמֵעִירוֹק לְתַמָּן וְהִיא זְעֵירָא אִשְׁתְּזֵב כְּעַן תַּמָּן הֲלָא זְעֵירָא הִיא וְתִתְקַיַּם נַפְשִׁי:
@54 וַאֲמַר לֵהּ הָא נְסֵיבִית אַפָּךְ אַף לְפִתְגָּמָא הָדֵין בְּדִיל דְּלָא לְמֵהְפַּךְ יָת קַרְתָּא דִּבְעִיתָא עֲלַהּ:
@55 אוֹחִי לְאִשְׁתֵּזֵב תַּמָּן אֲרֵי לָא אִכּוּל לְמֶעְבַּד פִּתְגָּמָא עַד מֵיתָךְ לְתַמָּן עַל כֵּן קְרָא שְׁמָא דְּקַרְתָּא צוֹעַר:
@56 שִׁמְשָׁא נְפַק עַל אַרְעָא וְלוֹט עַל לְצוֹעַר:
@57 וַיְיָ אַמְטַר עַל סְדוֹם וְעַל עֲמוֹרָה גָּפְרֵיתָא וְאֶשָּׁתָא מִן קֳדָם יְיָ מִן שְׁמַיָּא:
@58 וַהֲפַךְ יָת קִרְוַיָּא הָאִלֵּין וְיָת כָּל מֵישְׁרָא וְיָת כָּל יָתְבֵי קִרְוַיָּא וְצִמְחָא דְּאַרְעָא:
@59 וְאִסְתְּכִיאַת אִתְּתֵהּ מִבַּתְרוֹהִי וַהֲוַת קָמָא דְּמִלְחָא:
@60 וְאַקְדֵּים אַבְרָהָם בְּצַפְרָא לְאַתְרָא דִּשַׁמֵשׁ תַּמָּן בִּצְלוֹ קֳדָם יְיָ:
@61 וְאִסְתְּכִי עַל אַפֵּי סְדוֹם וַעֲמוֹרָה וְעַל כָּל אַפֵּי אַרְעָא דְּמֵישְׁרָא וַחֲזָא וְהָא סְלִיק תְּנָנָא דְּאַרְעָא כִּתְנָנָא דְּאַתּוּנָא:
@62 וַהֲוָה בְּחַבָּלוּת (נ''י כַּד חֲבַל) יְיָ יָת קִרְוֵי מֵישְׁרָא וּדְכִיר יְיָ יָת אַבְרָהָם וְשַׁלַּח יָת לוֹט מִגּוֹ הֲפֶכְתָּא כַּד הֲפַךְ יָת קִרְוַיָּא דִּי הֲוָה יָתֵב בְּהֵן לוֹט:
@63 וּסְלֵק לוֹט מִצּוֹעַר וִיתֵב בְּטוּרָא וְתַרְתֵּין בְּנָתֵהּ עִמֵּהּ אֲרֵי דָּחִיל לְמִתַּב בְּצוֹעַר וִיתֵב בִּמְעַרְתָּא הוּא וְתַרְתֵּין בְּנָתֵהּ:
@64 וַאֲמֶרֶת רַבְּתָא לִזְעֶרְתָּא אֲבוּנָא סִיב וּגְבַר לֵית בְּאַרְעָא לְמֵיעַל עֲלָנָא כְּאוֹרַח כָּל אַרְעָא:
@65 אִיתָא נַשְׁקֵי יָת אֲבוּנָא חַמְרָא וְנִשְׁכּוּב עִמֵּהּ וּנְקַיֵּם מֵאֲבוּנָא בְּנִין:
@66 וְאַשְׁקִיאָה יָת אֲבוּהֶן חַמְרָא בְּלֵילְיָא הוּא וְעַלַּת רַבְּתָא וּשְׁכִיבָא עִם אֲבוּהָא וְלָא יְדַע בְּמִשְׁכְּבַהּ וּבְקִימַהּ:
@67 וַהֲוָה בְּיוֹמָא דְבַתְרוֹהִי וַאֲמֶרֶת רַבְּתָא לִזְעֶרְתָּא הָא שְׁכֵיבִית רַמְשָׁא עִם אַבָּא נַשְׁקִנֵּהּ חַמְרָא אַף בְּלֵילְיָא וְעוּלִי שְׁכִיבִי עִמֵּהּ וּנְקַיֵּם מֵאֲבוּנָא בְּנִין:
@68 וְאַשְׁקִיאָה אַף בְּלֵילְיָא הַהוּא יָת אֲבוּהֶן חַמְרָא וְקָמַת זְעֶרְתָּא וּשְׁכִיבַת עִמֵּהּ וְלָא יְדַע בְּמִשְׁכְּבַהּ וּבְקִימַהּ:
@69 וְעַדִּיאַן תַּרְתֵּין בְּנַת לוֹט מֵאֲבוּהֶן:
@70 וִילִידַת רַבְּתָא בַּר וּקְרַת שְׁמֵהּ מוֹאָב הוּא אֲבוּהוֹן דְמוֹאָבָא עַד יוֹמָא דֵין:
@71 וּזְעֶרְתָּא אַף הִיא יְלִידַת בַּר וּקְרַת שְׁמֵהּ בַּר עַמִּי הוּא אֲבוּהוֹן דִּבְנֵי עַמּוֹן עַד יוֹמָא דֵין:
@72 וּנְטַל מִתַּמָּן אַבְרָהָם לְאַרְעָא דָּרוֹמָא וִיתֵב בֵּין רְקָם וּבֵין חַגְרָא וְאִתּוֹתַב בִּגְרָר:
@73 וַאֲמַר אַבְרָהָם עַל שָׂרָה אִתְּתֵהּ אֲחָתִי הִיא וּשְׁלַח אֲבִימֶלֶךְ מַלְכָּא דִּגְרָר וּדְבַר יָת שָׂרָה:
@74 וַאֲתָא מֵימַר מִן קָדָם יְיָ לְוַת אֲבִימֶלֶךְ בְּחֶלְמָא דְלֵילְיָא וַאֲמַר לֵהּ הָא אַתְּ מִית עַל עֵיסַק אִתְּתָא דִּדְבַרְתָּא וְהִיא אִתַּת גְּבָר:
@75 וַאֲבִימֶלֶךְ לָא קְרֵב לְוָתַהּ וַאֲמַר יְיָ הָעָם אַף זַכַּאי תִּקְטוֹל:
@76 הֲלָא הוּא אֲמַר לִי אֲחָתִי הִיא וְהִיא אַף הִיא אֲמָרַת אָחִי הוּא בְּקַשִּׁיטוּת לִבִּי וּבְזַכָּאוּת יָדַי עֲבָדִית דָּא:
@77 וַאֲמַר לֵהּ מֵימַר מִן קֳדָם יְיָ בְּחֶלְמָא אַף קֳדָמַי גְּלִי אֲרֵי בְּקַשִּׁיטוּת לִבָּךְ עֲבַדְתָּ דָּא וּמְנָעִית אַף אֲנָא יָתָךְ מִלְּמֶחְטֵי קֳדָמָי עַל כֵּן לָא שְׁבָקְתָּךְ לְמִקְרַב לְוָתַהּ:
@78 וּכְעַן אֲתֵיב אִתַּת גַּבְרָא אֲרֵי נְבִיָּא הוּא וִיצַלֵּי עֲלָךְ וּתְחֵי וְאִם לֵיתָךְ מֵתֵיב דַּע אֲרֵי מֵימַת תְּמוּת אַתְּ וְכָל דִּי לָךְ:
@79 וְאַקְדֵּים אֲבִימֶלֶךְ בְּצַפְרָא וּקְרָא לְכָל עַבְדּוֹהִי וּמַלִּיל יַת כָּל פִּתְגָּמַיָּא הָאִלֵּין קֳדָמֵיהוֹן וּדְחִילוּ גּוּבְרַיָּא לַחֲדָא:
@80 וּקְרָא אֲבִימֶלֶךְ לְאַבְרָהָם וַאֲמַר לֵהּ מָה עֲבַדְתָּ לָנָא וּמָה חָבִית (נ''י חָטֵית) לָךְ אֲרֵי אַיְתֵיתָא עֲלַי וְעַל מַלְכוּתִי חוֹבָא רַבָּא עוֹבָדִין דִּי לָא כָשְׁרִין לְאִתְעֲבָדָא עֲבַדְתָּ עִמִּי:
@81 וַאֲמַר אֲבִימֶלֶךְ לְאַבְרָהָם מָה חָזֵיתָ אֲרֵי עֲבַדְתָּ יָת פִתְגָּמָא הָדֵין:
@82 וַאֲמַר אַבְרָהָם אֲרֵי אֲמָרִית לְחוֹד לֵית דַּחַלְתָּא דַּיְיָ בְּאַתְרָא הָדֵין וְיִקְטְלֻנַּנִי עַל עֵיסַק אִתְּתִי:
@83 וּבְרַם בְּקוּשְׁטָא אֲחָתִי בַּת אַבָּא הִיא בְּרַם לָא בַת אִמִּי וַהֲוַת לִי לְאִנְתּוּ:
@84 וַהֲוָה כַּד טָעוּ עַמְמַיָּא בָּתַר עוֹבָדֵי יְדֵיהוֹן יָתִי קָרִיב יְיָ לְדַחַלְתֵּהּ מִבֵּית אַבָּא וַאֲמָרִית לַהּ דֵּין (נ''י דָּא) טֵיבוּתִיךְ דִּי תַעְבְּדִי עִמִּי לְכָל אַתְרָא דִּי נְהַךְ לְתַמָּן אֱמָרִי עֲלַי אָחִי הוּא:
@85 וּדְבַר אֲבִימֶלֶךְ עָאן וְתוֹרִין וְעַבְדִין וְאַמְהָן וִיהַב לְאַבְרָהָם וַאֲתֵיב לֵהּ יָת שָׂרָה אִתְּתֵהּ:
@86 וַאֲמַר אֲבִימֶלֶךְ הָא אַרְעִי קֳדָמָךְ בִּדְתַקִּין בְּעֵינָיךְ תִּיב:
@87 וּלְשָׂרָה אֲמַר הָא יְהָבִית אֶלֶף סַלְעִין דִּכְסַף לְאָחִיךְ הָא הוּא לִיךְ כְּסוּת דִּיקָר עַיְנִין חֳלַף דִּשְׁלָחִית וּדְּבַרְתִּיךְ וַחֲזֵית יָתִיךְ וְיָת כָּל דְּעִמָּךְ וְעַל כָּל מָה דַּאֲמָרַת אִתּוֹכָחַת:
@88 וְצַלִּי אַבְרָהָם קֳדָם יְיָ וְאַסִּי יְיָ יָת אֲבִימֶלֶךְ וְיָת אִתְּתֵהּ וְאַמְהָתֵהּ וְאִתְרְוָחוּ:
@89 אֲרֵי מֵיחַד אֲחַד יְיָ בְּאַפֵּי כָל פָּתַח וַלְדָא לְבֵית אֲבִימֶלֶךְ עַל עֵיסַק שָׂרָה אִתַּת אַבְרָהָם:
@90 וַיְיָ דְּכִיר יָת שָׂרָה כְּמָא דִּי אֲמַר וַעֲבַד יְיָ לְשָׂרָה כְּמָא דִּי מַלִּיל:
@91 וְעַדִּיאַת וִילִידַת שָׂרָה לְאַבְרָהָם בַּר לְסִיבְתוֹהִי לִזְמַן דִּי מַלִּיל יָתֵהּ יְיָ:
@92 וּקְרָא אַבְרָהָם יָת שׁוּם בְּרֵהּ דְאִתְיְלִיד לֵהּ דִּילִידַת לֵהּ שָׂרָה יִצְחָק:
@93 וּגְזַר אַבְרָהָם יָת יִצְחָק בְּרֵהּ בַּר תְּמַנְיָא יוֹמִין כְּמָא דִּי פַקִּיד יָתֵהּ יְיָ:
@94 וְאַבְרָהָם בַּר מְאָה שְׁנִין כַּד אִתְיְלִיד לֵהּ יָת יִצְחָק בְּרֵהּ:
@95 וַאֲמֶרֶת שָׂרָה חֶדְוָא עֲבַד לִי יְיָ כָּל דִּשְׁמַע יֶחֱדֵּי לִי:
@96 וַאֲמֶרֶת מָאן מְהֵימָן דַּאֲמַר לְאַבְרָהָם קַיָּם דְּתוֹנִיק בְּנִין שָׂרָה אֲרֵי יְלֵידִית בַּר לְסִיבְתוֹהִי:
@97 וּרְבָא רַבְיָא וְאִתְחֲסִיל וַעֲבַד אַבְרָהָם מִשְׁתְּיָא רַבָּא בְּיוֹמָא דְּאִתְחֲסִיל יָת יִצְחָק:
@98 וַחֲזַת שָׂרָה יָת בַּר הָגָר מִצְרֵיתָא דִּילִידַת לְאַבְרָהָם מְחָיִיךְ:
@99 וַאֲמֶרֶת לְאַבְרָהָם תָּרֵךְ אַמְתָא הָדָא וְיָת בְּרַהּ אֲרֵי לָא יֵרַת בַּר אַמְתָא הָדָא עִם בְּרִי עִם יִצְחָק:
@100 וּבְאֵישׁ פִּתְגָּמָא לַחֲדָא בְּעֵינֵי אַבְרָהָם עַל עֵיסַק בְּרֵהּ:
@101 וַאֲמַר יְיָ לְאַבְרָהָם לָא יַבְאֵשׁ בְּעֵינָיךְ עַל עוּלֵימָא וְעַל אַמְתָךְ כֹּל דִּי תֵימַר לָךְ שָׂרָה קַבֵּל מִנַּהּ אֲרֵי בְיִצְחָק יִתְקְרוּן לָךְ בְּנִין:
@102 וְאַף יָת בַּר אַמְתָא לְעַם אֲשַׁוִּנֵּהּ אֲרֵי בְנָךְ הוּא:
@103 וְאַקְדֵּים אַבְרָהָם בְּצַפְרָא וּנְסִיב לַחֲמָא וְרָקְבָּא דְמַיָּא וִיהַב לְהָּגָר שַׁוֵי עַל כַּתְפַּהּ וְיָת רַבְיָא וְשַׁלְחַהּ וַאֲזָלַת וְתָעַת בְּמַדְבְּרָא (נ''א בְּמַדְבֵּר) בְּאֵר שָׁבַע:
@104 וּשְׁלִימוּ מַיָּא מִן רָקְבָּא וּרְמַת יָת רַבְיָא תְּחוֹת חַד מִן אִילָנַיָּא:
@105 וַאֲזָלַת וִיתִיבַת לַהּ מִקֳּבֵל אַרְחֵיקַת (נ''י אַרְחִיק) כְּמֵיגַד קַשְׁתָּא אֲרֵי אֲמֶרֶת לָא אֶחֱזֵי בְּמוֹתָא דְרַבְיָא וִיתִיבַת מִקֳּבֵל וַאֲרֵימַת יָת קָלַהּ וּבְכָת:
@106 וּשְׁמִיעַ קֳדָם יְיָ יָת קָלֵהּ דְּרַבְיָא וּקְרָא מַלְאֲכָא דַּיְיָ לְהָגָר מִן שְׁמַיָּא וַאֲמַר לַהּ מָה לָיךְ הָגָר לָא תִדְחֲלִי אֲרֵי שְׁמִיעַ קֳדָם יְיָ יָת קָלֵהּ דְּרַבְיָא בַּאֲתַר דְּהוּא תַמָּן:
@107 קוּמִי טוּלִי יָת רַבְיָא וְאַתְקִיפִי יָת יְדֵךְ בֵּהּ אֲרֵי לְעַם סַגִּי אֲשַׁוִּנֵּהּ:
@108 וּגְלָא יְיָ יָת עֵינָהַהּ וַחֲזַת בֵּירָא דְמַיָּא וַאֲזָלַת וּמְלַת יָת רָקְבָּא מַיָּא וְאַשְׁקִיאַת יָת רַבְיָא:
@109 וַהֲוָה מֵימְרָא דַּיְיָ בְּסַעְדֵהּ דְּרַבְיָא וּרְבָא וִיתֵב בְּמַדְבְּרָא וַהֲוָה רָבֵי קַשְׁתָּא:
@110 וִיתֵב בְּמַדְבְּרָא דְפָארָן וּנְסִיבַת לֵהּ אִמֵּהּ אִתְּתָא מֵאַרְעָא דְמִצְרָיִם:
@111 וַהֲוָה בְּעִדָּנָא הַהִיא וַאֲמַר אֲבִימֶלֶךְ וּפִיכֹל רַב חֵילֵהּ לְאַבְרָהָם לְמֵימָר מֵימְרָא דַּיְיָ בְּסַעְדָּךְ בְּכֹל דִּי אַתְּ עָבֵד:
@112 וּכְעַן קַיֵּם לִי בְּמֵימְרָא דַּיְיָ הָכָא דְּלָא תְשַׁקַּר בִּי וּבִבְרִי וּבְבַר בְּרִי כְּטִיבוֹתָא דִּי עֲבָדִית עִמָּךְ תַּעְבֵּד עִמִּי וְעִם אַרְעָא דְאִתּוֹתַבְתָּא בַהּ:
@113 וַאֲמַר אַבְרָהָם אֲנָא אֲקַיֵּם:
@114 וְאוֹכַח אַבְרָהָם יָת אֲבִימֶלֶךְ עַל עֵיסַק בֵּירָא דְמַיָּא דִּי אֲנִּיסוּ עַבְדֵי אֲבִימֶלֶךְ:
@115 וַאֲמַר אֲבִימֶלֶךְ לָא יְדָעִית מָאן עֲבַד יָת פִּתְגָּמָא הָדֵין וְאַף אַתְּ לָא חַוֵּיתָ לִּי וְאַף אֲנָא לָא שְׁמָעִית אֱלָּהֵין יוֹמָא דֵין:
@116 וּדְבַר אַבְרָהָם עָאן וְתוֹרִין וִיהַב לַאֲבִימֶלֶךְ וּגְזָרוּ תַרְוֵיהוֹן קְיָם:
@117 וַאֲקִים אַבְרָהָם יָת שְׁבַע חוּרְפַן דְּעָאן בִּלְחוֹדֵיהֶן:
@118 וַאֲמַר אֲבִימֶלֶךְ לְאַבְרָהָם מָה אִנּוּן שְׁבַע חוּרְפַן אִלֵּין דַּאֲקֵמְתָּא בִּלְחוֹדֵיהֶן:
@119 וַאֲמַר אֲרֵי יָת שְׁבַע חוּרְפַן תְּקַבֵּל מִן יְדִי בְּדִיל דִּתְהֵי לִי לְסַהֲדוּ אֲרֵי חֲפָרִית יָת בֵּירָא הָדָא:
@120 עַל כֵּן קְרָא לְאַתְרָא הַהוּא בְּאֵר שָׁבַע אֲרֵי תַמָּן קַיָּמוּ תַּרְוֵיהוֹן:
@121 וּגְזָרוּ קְיָם בִּבְאֵר שָׁבַע וְקָם אֲבִימֶלֶךְ וּפִיכֹל רַב חֵילֵהּ וְתָבוּ לְאַרַע פְּלִשְׁתָּאֵי:
@122 וּנְצִיב נִצְבָּא (נ''י אִילָנָא) בִּבְאֵר שָׁבַע וְצַלִּי תַמָּן בִּשְׁמָא דַּיְיָ אֱלָהָא דְעַלְמָא:
@123 וְאִתּוֹתָב אַבְרָהָם בְּאַרַע פְּלִשְׁתָּאֵי יוֹמִין סַגִּיאִין:
@124 וַהֲוָה בָּתַר פִּתְגָּמַיָּא הָאִלֵּין וַיְיָ נַסִּי יָת אַבְרָהָם וַאֲמַר לֵהּ אַבְרָהָם וַאֲמַר הָא אֲנָא:
@125 וַאֲמַר דְּבַר כְּעַן יָת בְּרָךְ יָת יְחִידָךְ דִּי רְחַמְתָּ יָת יִצְחָק וְאִיזֵל לָךְ לְאַרְעָא פּוּלְחָנָא וְאַסְקֵהּ קֳדָמַי תַּמָּן לַעֲלָתָא עַל חַד מִן טוּרַיָּא דִּי אֵימַר לָךְ:
@126 וְאַקְדֵּים אַבְרָהָם בְּצַפְרָא וְזָרֵז יָת חֲמָרֵהּ וּדְבַר יָת תְּרֵין עוּלֵימוֹהִי עִמֵּהּ וְיָת יִצְחָק בְּרֵהּ וְצַלַּח אָעֵי לַעֲלָתָא וְקָם וַאֲזַל לְאַתְרָא דִּי אֲמַר לֵהּ יְיָ:
@127 בְּיוֹמָא תְלִיתָאָה וּזְקַף אַבְרָהָם יָת עֵינוֹהִי וַחֲזָא יָת אַתְרָא מֵרָחִיק:
@128 וַאֲמַר אַבְרָהָם לְעוּלֵימוֹהִי אוֹרִיכוּ לְכוֹן הָכָא עִם חֲמָרָא וַאֲנָא וְעוּלֵימָא נִתְמְטֵי עַד כָּא וְנִסְגּוּד וּנְתוּב לְוַתְכוֹן:
@129 וּנְסֵיב אַבְרָהָם יָת אָעֵי דַּעֲלָתָא וְשַׁוִּי עַל יִצְחָק בְּרֵהּ וּנְסֵיב בִּידֵהּ יָת אֶשָּׁתָא וְיָת סַכִּינָא וַאֲזָלוּ תַרְוֵיהוֹן כַּחֲדָא:
@130 וַאֲמַר יִצְחָק לְאַבְרָהָם אֲבוּהִי וַאֲמַר אַבָּא וַאֲמַר הָא אֲנָא בְרִי וַאֲמַר הָא אֶשָּׁתָא וְאָעַיָּא וְאָן אִימְרָא לַעֲלָתָא:
@131 וַאֲמַר אַבְרָהָם קֳדָם יְיָ גְּלֵי לֵהּ אִימְרָא לַעֲלָתָא בְּרִי וַאֲזָלוּ תַרְוֵיהוֹן כַּחֲדָא:
@132 וְאָתוּ לְאַתְרָא דִּי אֲמַר לֵהּ יְיָ וּבְנָא תַמָּן אַבְרָהָם יָת מַדְבְּחָא וְסַדַּר יָת אָעַיָּא וַעֲקַד יָת יִצְחָק בְּרֵהּ וְשַׁוֵּי יָתֵהּ עַל מַדְבְּחָא עֵיל מִן אָעַיָּא:
@133 וְאוֹשִׁיט אַבְרָהָם יָת יְדֵהּ וּנְסֵיב יָת סַכִּינָא לְמֵיכַס יַת בְּרֵהּ:
@134 וּקְרָא לֵהּ מַלְאָכָא דַּיְיָ מִן שְׁמַיָּא וַאֲמַר אַבְרָהָם אַבְרָהָם וַאֲמַר הָא אֲנָא:
@135 וַאֲמַר לָא תוֹשִׁיט יְדָךְ לְעוּלֵימָא וְלָא תַעְבֵּד לֵהּ מִדָּעָם אֲרֵי כְּעַן יְדַעְנָא (נ''י יְדָעִית) אֲרֵי דַּחֲלָא דַּיְיָ אַתְּ וְלָא מְנַעְתָּ יָת בְּרָךְ יָת יְחִידָךְ מִנִּי:
@136 וּזְקַף אַבְרָהָם יָת עֵינוֹהִי בָּתַר אִלֵּין וַחֲזָא וְהָא דִּכְרָא בָּתַר אֲחִיד בְּאִילָנָא בְּקַרְנוֹהִי וַאֲזַל אַבְרָהָם וּנְסֵיב יָת דִּכְרָא וְאַסְקֵהּ לַעֲלָתָא חֲלַף בְּרֵהּ:
@137 וּפְלַח וְצַלִּי אַבְרָהָם תַּמָּן בְּאַתְרָא הַהוּא וַאֲמַר קֳדָם יְיָ הָכָא יְהוֹן פַּלְחַן דָּרַיָּא בְּכֵן יִתְאֲמַר בְּיוֹמָא הָדֵין בְּטוּרָא הָדֵין אַבְרָהָם קֳדָם יְיָ פְּלָח:
@138 וּקְרָא מַלְאָכָא דַּיְיָ לְאַבְרָהָם תִּנְיָנוּת מִן שְׁמַיָּא:
@139 וַאֲמַר בְּמֵימְרִי קַיֵּמִית אֲמַר יְיָ אֲרֵי חֲלַף דִּי עֲבַדְתָּא יָת פִּתְגָּמָא הָדֵין וְלָא מְנַעְתָּא יָת בְּרָךְ יָת יְחִידָךְ:
@140 אֲרֵי בָרָכָא אֲבָרְכִנָּךְ וְאַסְגָּאָה אַסְגֵּי יָת בְּנָיךְ כְּכוֹכְבֵי שְׁמַיָּא וּכְחָלָא דִּי עַל כֵּיף יַמָּא וְיִרְתוּן בְּנָיךְ יָת קִרְוֵי סַנְאֵיהוֹן:
@141 וְיִתְבָּרְכוּן בְּדִיל בְּנָיךְ כֹּל עַמְמַיָּא דְאַרְעָא חֲלַף דִּי קַבֵּלְתָּא לְמֵימְרִי:
@142 וְתַב אַבְרָהָם לְוָת עוּלֵימוֹהִי וְקָמוּ וַאֲזָלוּ כַחֲדָא לִבְאֵר שָׁבַע וִיתֵיב אַבְרָהָם בִּבְאֵר שָׁבַע:
@143 וַהֲוָה בָּתַר פִּתְגָּמַיָּא הָאִלֵּין וְאִתְחֲוָא לְאַבְרָהָם לְמֵימָר הָא יְלֵידַת מִלְכָּה אַף הִיא בְּנִין לְנָחוֹר אָחוּךְ:
@144 יָת עוּץ בּוּכְרֵהּ וְיָת בּוּז אָחוּהִי וְיָת קְמוּאֵל אֲבוּהִי דַּאֲרָם:
@145 וְיָת כֶּשֶׂד וְיָת חֲזוֹ וְיָת פִּלְדָּשׁ וְיָת יִדְלָף ויָת בְּתוּאֵל:
@146 וּבְתוּאֵל:אוֹלִיד יָת רִבְקָה תְּמַנְיָא אִלֵּין יְלֵידַת מִלְכָּה לְנָחוֹר אֲחוּהִי דְאַבְרָהָם:
@147 וּלְחֵנָתֵהּ וּשְׁמַהּ רְאוּמָה וִילֵידַת אַף הִיא יָת טֶבַח וְיָת גַּחַם וְיָת תַּחַשׁ וְיָת מַעֲכָה: פפפ:

@1 **וירא אליו.** לבקר את החולה. אמר רבי חמא בר חנינא יום שלישי למילתו היה, ובא הקדוש ברוך הוא ושאל בשלומו: **באלוני ממרא.** הוא שנתן לו עצה על המילה, לפיכך נגלה עליו בחלקו: **ישב.** ישב כתיב, בקש לעמוד, אמר לו הקדוש ברוך הוא שב ואני אעמד, ואתה סימן לבניך, שעתיד אני להתיצב בעדת הדינין והן יושבין, שנאמר (תהלים פב א) אלהים נצב בעדת אל: **פתח האהל.** לראות אם יש עובר ושב ויכניסם בביתו: **כחם היום.** הוציא הקדוש ברוך הוא חמה מנרתיקה שלא להטריחו באורחים, ולפי שראהו מצטער שלא היו אורחים באים, הביא המלאכים עליו בדמות אנשים:
@2 **והנה שלשה אנשים.** אחד לבשר את שרה ואחד להפוך את סדום ואחד לרפאות את אברהם, שאין מלאך אחד עושה שתי שליחיות. תדע לך שכן כל הפרשה הוא מזכירן בלשון רבים (פסוק ח) ויאכלו (פסוק ט) ויאמרו אליו, ובבשורה נאמר (שם י) ויאמר שוב אשוב אליך, ובהפיכת סדום הוא אומר (יט כב) כי לא אוכל לעשות דבר, (שם כא) , לבלתי הפכי. ורפאל שרפא את אברהם הלך משם להציל את לוט, הוא שנאמר (שם יז) ויהי כהוציאם אותם החוצה ויאמר המלט על נפשך, למדת שהאחד היה מציל: **נצבים עליו.** לפניו, כמו (במדבר ב כ) ועליו מטה מנשה. אבל לשון נקיה היא כלפי המלאכים: **וירא.** מהו וירא וירא שני פעמים, הראשון כמשמעו והשני לשון הבנה, נסתכל שהיו נצבים במקום אחד והבין שלא היו רוצים להטריחו ואף על פי שיודעים היו שיצא לקראתם, עמדו במקומם לכבודו ולהראותו שלא רצו להטריחו, וקדם הוא ורץ לקראתם. בבבא מציעא (פו ב) כתיב נצבים עליו, וכתיב וירץ לקראתם, כד חזיוה דהוה שרי ואסר פרשו המנו, מיד וירץ לקראתם:
@3 **ויאמר אדני אם נא** וגו' **.** לגדול שבהם אמר, וקראם כלם אדונים ולגדול אמר אל נא תעבר, וכיון שלא יעבר הוא, יעמדו חבריו עמו, ובלשון זה הוא חול. דבר אחר קודש הוא, והיה אומר להקדוש ברוך הוא להמתין לו עד שירוץ ויכניס את האורחים. ואף על פי שכתוב אחר (פסוק ב) וירץ לקראתם, האמירה קודם לכן היתה, ודרך המקראות לדבר כן, כמו שפרשתי אצל (ו ג) לא ידון רוחי באדם, שנכתב אחר ויולד נח (ה לב) , ואי אפשר לומר אלא אם כן קודם הגזרה עשרים שנה, ושתי הלשונות בבראשית רבה (מח י) :
@4 **יקח נא.** על ידי שליח, והקדוש ברוך הוא שלם לבניו על ידי שליח שנאמר (במדבר כ יא) וירם משה את ידו ויך את הסלע: **ורחצו רגליכם.** כסבור שהם ערביים שמשתחוים לאבק רגליהם והקפיד שלא להכניס עבודה זרה לביתו. אבל לוט שלא הקפיד, הקדים לינה לרחיצה, שנאמר (יט ב) ולינו ורחצו רגליכם: **תחת העץ.** תחת האילן:
@5 **וסעדו לבכם.** בתורה בנביאים ובכתובים מצינו דפתא סעדתא דלבא. בתורה סעדו לבכם. בנביאים (שופטים יט ה) סעד לבך פת לחם. בכתובים (תהלים קד טו) ולחם לבב אנוש יסעד. אמר רבי חמא לבבכם אין כתיב כאן אלא לבכם, מגיד שאין יצר הרע שולט במלאכים: **אחר תעבורו.** אחר כן תלכו: **כי על כן עברתם.** כי הדבר הזה אני מבקש מכם מאחר שעברתם עלי לכבודי: **כי על כן.** כמו על אשר, וכן כל כי על כן שבמקרא (לקמן יט ח) כי על כן באו בצל קורתי, (לקמן לג י) כי על כן ראיתי פניך, (שם לח כו) כי על כן לא נתתיה, (במדבר י לא) כי על כן ידעת חנותנו:
@6 **קמח סלת.** סלת לעוגות, קמח לעמילן של טבחים, לכסות את הקדרה, ולשאוב את הזהמא:
@7 **בן בקר רך וטוב.** שלשה פרים היו כדי להאכילן שלש לשונות בחרדל: **אל הנער.** זה ישמעאל לחנכו במצות:
@8 **ויקח חמאה** וגו' **.** ולחם לא הביא לפי שפרסה שרה נדה, שחזר לה אורח כנשים אותו היום, ונטמאת העיסה: **חמאה.** שומן החלב שקולטין מעל פניו: **ובן הבקר אשר עשה.** אשר תקן, קמא קמא שתקן, אמטי ואייתי קמייהו: **ויאכלו.** נראו כמו שאכלו, מכאן שלא ישנה אדם מן המנהג:
@9 **ויאמרו אליו.** נקוד על אי''ו שבאליו, ותניא רבי שמעון בן אלעזר אומר כל מקום שהכתב רבה על הנקדה אתה דורש הכתב וכו' , וכאן הנקדה רבה על הכתב אתה דורש הנקודה, שאף לשרה שאלו איו אברהם, למדנו שישאל אדם באכסניא שלו לאיש על האשה ולאשה על האיש **.** בבבא מציעא (פז א) אומרים יודעים היו מלאכי השרת שרה אמנו היכן היתה, אלא להודיע שצנועה היתה כדי לחבבה על בעלה. אמר רבי יוסי בר חנינא כדי לשגר לה כוס של ברכה: **הנה באהל.** צנועה היא:
@10 **שוב אשוב.** לא בשרו המלאך שישוב אליו אלא בשליחותו של מקום אמר לו, כמו (טז י) ויאמר לה מלאך ה' הרבה ארבה, והוא אין בידו להרבות, אלא בשליחותו של מקום, אף כאן בשליחותו של מקום אמר לו כן. אלישע אמר לשונמית (מלכים ב' ד טז) למועד הזה כעת חיה את חובקת בן ותאמר אל אדוני איש האלהים אל תכזב בשפחתך, אותן המלאכים שבשרו את שרה אמרו למועד אשוב. אמר לה אלישע אותם המלאכים שהם חיים וקיימים לעולם אמרו למועד אשוב, אבל אני בשר ודם שהיום חי ומחר מת, בין חי ובין מת למועד הזה וגו' : **כעת חיה.** כעת הזאת לשנה הבאה, ופסח היה, ולפסח הבא נלד יצחק, מדלא קרינן כעת אלא כעת. **כעת חיה.** כעת הזאת שתהא חיה לכם שתהיו כלכם שלמים וקימים: **והוא אחריו.** הפתח היה אחר המלאך:
@11 **חדל להיות.** פסק ממנה: **ארח כנשים.** אורח נדות:
@12 **בקרבה.** מסתכלת במעיה ואמרה אפשר הקרבים הללו טעונין ולד, השדים הללו שצמקו מושכין חלב, תנחומא (שופטים יח) : **עדנה.** צחצוח בשר, ולשון משנה (מנחות פו א) משיר את השער ומעדן את הבשר. דבר אחר לשון עדן, זמן וסת נדות:
@13 **האף אמנם.** הגם אמת אלד: **ואני זקנתי.** שנה הכתוב מפני השלום, שהרי היא אמרה ואדוני זקן:
@14 **היפלא.** כתרגומו היתכסי, וכי שום דבר מפלא ומפרד ומכסה ממני מלעשות כרצוני: **למועד.** לאותו מועד המיחד שקבעתי לך אתמול למועד הזה בשנה האחרת:
@15 **כי יראה** וגו' **כי צחקת.** הראשון משמש לשון דהא שנותן טעם לדבר ותכחש שרה לפי שיראה, והשני משמש בלשון אלא, ויאמר לא כדבריך הוא אלא צחקת, שאמרו רבותינו כי משמש בארבע לשונות אי, דילמא, אלא, דהא:
@16 **וישקיפו על פני סדום.** כל השקפה שבמקרא לרעה חוץ מהשקיפה ממעון קדשך (דברים כו טו) , שגדול כח מתנות עניים שהופך מדת רגז לרחמים: **לשלחם.** ללוותם, כסבור אורחים הם:
@17 **המכסה אני.** בתמיהה: **אשר אני עושה.** בסדום, לא יפה לי לעשות דבר זה שלא מדעתו, אני נתתי לו את הארץ הזאת, וחמשה כרכין הללו שלו הן, שנאמר (י יט) גבול הכנעני מצידן וגו' באכה סדמה ועמרה וגו' . קראתי אותו אברהם, אב המון גוים, ואשמיד את הבנים ולא אודיע לאב שהוא אוהבי:
@18 **ואברהם היו יהיה.** מדרש אגדה (משלי י ז) זכר צדיק לברכה, הואיל והזכירו ברכו. ופשוטו וכי ממנו אני מעלים, והרי הוא חביב לפני להיות לגוי גדול ולהתברך בו כל גויי הארץ:
@19 **כי ידעתיו.** לשון חבה, כמו (רות ב א) מודע לאישה, (שם ג ב) הלא בעז מדעתנו, (שמות לג יז) ואדעך בשם, ואמנם עיקר לשון כלם אינו אלא לשון ידיעה, שהמחבב את האדם מקרבו אצלו ויודעו ומכירו. ולמה ידעתיו, למען אשר יצוה לפי שהוא מצוה את בניו עלי לשמור דרכי. ואם תפרשהו כתרגומו יודע אני בו שיצוה את בניו וגו' , אין למען נופל על הלשון: **יצוה.** לשון הוה, כמו (איוב א ה) ככה יעשה איוב: **למען הביא.** כך הוא מצוה לבניו שמרו דרך ה' כדי שיביא ה' על אברהם וגו' . על בית אברהם לא נאמר, אלא על אברהם, למדנו כל המעמיד בן צדיק כאלו אינו מת:
@20 **ויאמר ה'.** אל אברהם, שעשה כאשר אמר שלא יכסה ממנו: **כי רבה.** כל רבה שבמקרא הטעם למטה בבי''ת, לפי שהן מתורגמין גדולה, או גדלה והולכת, אבל זה טעמו למעלה ברי''ש, לפי שמתורגם גדלה כבר, כמו שפירשתי לעיל (טו יז) ויהי השמש באה, (רות א טו) הנה שבה יבמתך:
@21 **ארדה נא ואראה.** למד לדינים שלא יפסקו דיני נפשות אלא בראיה, הכל כמו שפרשתי בפרשת הפלגה (לעיל יא ז) . דבר אחר ארדה נא לסוף מעשיהם: **הכצעקתה.** של מדינה: **הבאה אלי עשו.** ואם עומדים במרדם כלה אני עושה בהם. ואם לא יעמדו במרדן, אדעה מה אעשה להפרע מהן ביסורין ולא אכלה אותן. וכיוצא בו מצינו במקום אחר (שמות לג ה) ועתה הורד עדיך מעליך ואדעה מה אעשה לך, ולפיכך יש הפסק נקדת פסק בין עשו לכלה, כדי להפריד תיבה מחברתה. ורבותינו דרשו הכצעקתה, צעקת ריבה אחת שהרגוה מיתה משנה על שנתנה מזון לעני, כמפורש בחלק (סנהדרין קט ב) :
@22 **ויפנו משם.** ממקום שאברהם לום שם: **ואברהם עודנו עומד לפני ה'.** והלא לא הלך לעמוד לפניו אלא הקדוש ברוך הוא בא אצלו ואמר לו (פסוק כ) זעקת סדום ועמורה כי רבה, והיה לו לכתוב וה' עודנו עומד לפני אברהם, אלא תקון סופרים הוא זה (אשר הפכוהו זכרונם לברכה לכתוב כן) :
@23 **ויגש אברהם.** מצינו הגשה למלחמה (ש''ב י יג) ויגש יואב וגו' , הגשה לפיוס (להלן מד יח) ויגש אליו יהודה, והגשה לתפלה (מלכים א' יח לו) ויגש אליהו הנביא, ולכל אלה נכנס אברהם, לדבר קשות, ולפיוס ולתפלה: **האף תספה.** הגם תספה. ולתרגום של אנקלוס שתרגמו לשון רוגז, כך פרושו האף ישיאך שתספה צדיק עם רשע:
@24 **אולי יש חמשים צדיקים.** עשרה צדיקים לכל כרך וכרך, כי חמשה מקומות יש:
@25 **חלילה לך.** ואם תאמר לא יצילו הצדיקים את הרשעים, למה תמית הצדיקים: **חלילה לך.** חלין הוא לך, יאמרו כך הוא אמנתו, שוטף הכל, צדיקים ורשעים, כך עשית לדור המבול ולדור הפלגה: **כדבר הזה.** לא הוא ולא כיוצא בו: **חלילה לך.** לעולם הבא: **השופט כל הארץ.** נקוד בחטף פת''ח ה''א של השופט לשון תמה, וכי מי שהוא שופט לא יעשה משפט אמת:
@26 **אם אמצא בסדום** וגו' **לכל המקום.** לכל הכרכים, לפי שסדום היתה מטרופולין וחשובה מכלם תלה בה הכתוב:
@27 **ואנכי עפר ואפר.** וכבר הייתי ראוי להיות עפר על ידי המלכים, ואפר על ידי נמרוד, לולי רחמיך אשר עמדו לי:
@28 **התשחית בחמשה.** והלא הן תשעה לכל כרך, ואתה צדיקו של עולם תצטרף עמהם:
@29 **אולי ימצאון שם ארבעים.** וימלטו ארבעה הכרכים, וכן שלשים יצילו שלשה מהם או עשרים יצילו שנים מהם או עשרה יצילו אחד מהם:
@31 **הואלתי.** רציתי כמו (שמות ב כא) ויואל משה:
@32 **אולי ימצאון שם עשרה.** על פחות לא בקש. אמר, דור המבול היו שמונה, נח ובניו ונשיהם ולא הצילו על דורם, ועל תשעה על ידי צרוף כבר בקש ולא מצא:
@33 **וילך ה'** וגו' **.** כיון שנשתתק הסניגור הלך לו הדין: **ואברהם שב למקומו.** נסתלק הדין נסתלק הסניגור והקטיגור מקטרג, ולפיכך (יט א) ויבאו שני המלאכים סדומה [בערב] להשחית. אחד להשחית את סדום ואחד להציל את לוט, והוא אותו שבא לרפאות את אברהם. והשלישי שבא לבשר את שרה, כיון שעשה שליחותו נסתלק לו:
@34 **המלאכים.** ולהלן קראם אנשים, כשהיתה שכינה עמהם קראם אנשים. דבר אחר אצל אברהם שכחו גדול והיו המלאכים תדירין אצלו כאנשים קראם אנשים, ואצל לוט קראם מלאכים: **בערב.** וכי כל כך שהו המלאכים מחברון לסדום, אלא מלאכי רחמים היו, וממתינים שמא יוכל אברהם ללמד עליהם סניגוריא: **ולוט ישב בשער סדום.** ישב כתיב, אותו היום מנוהו שופט עליהם: **וירא לוט** וגו' **.** מבית אברהם למד לחזר על האורחים:
@35 **הנה נא אדני.** הנה נא אתם אדונים לי אחר שעברתם עלי. דבר אחר הנה נא צריכים אתם לתת לב על הרשעים הללו שלא יכירו בכם. וזו היא עצה נכונה: **סורו נא.** עקמו את הדרך לביתי דרך עקלתון, שלא יכירו שאתם נכנסין שם לכך נאמר סורו (בב''ר נ ז) : **ולינו ורחצו רגליכם.** וכי דרכן של בני אדם ללון תחלה ואחר כך לרחוץ, ועוד שהרי אברהם אמר להם תחלה (יח ד) ורחצו רגליכם. אלא כך אמר לוט אם כשיבאו אנשי סדום ויראו שכבר רחצו רגליהם, יעלילו עלי ויאמרו כבר עברו שני ימים או שלשה שבאו לביתך ולא הודעתנו, לפיכך אמר מוטב שיתעכבו כאן באבק רגליהם שיהיו נראין כמו שבאו עכשיו, לפיכך אמר לינו תחלה ואחר כך רחצו: **ויאמרו לא.** לאברהם אמרו (יח ה) כן תעשה, מכאן שמסרבין לקטן ואין מסרבין לגדול **כי ברחוב נלין.** הרי כי משמש בלשון אלא, שאמרו לא נסור אל ביתך אלא ברחובה של עיר נלין:
@36 **ויסרו אליו.** עקמו את הדרך לצד ביתו: **ומצות אפה.** פסח היה:
@37 **טרם ישכבו ואנשי העיר אנשי סדום.** כך נדרש בבראשית רבה (נ ה) טרם ישכבו ואנשי העיר היו בפיהם של מלאכים, שהיו שואלים ללוט מה טיבם ומעשיהם, והוא אומר להם רבם רשעים. עודם מדברים בהם ואנשי סדום וגו' . ופשוטו של מקרא ואנשי העיר, אנשי רשע, נסבו על הבית. על שהיו רשעים נקראים אנשי סדום, כמו שאמר הכתוב (יג יג) ואנשי סדום רעים וחטאים: **כל העם מקצה.** מקצה העיר עד הקצה, שאין אחד מהם מוחה בידם, שאפלו צדיק אחד אין בהם:
@38 **ונדעה אתם.** במשכב זכר, כמו (פס' ח) אשר לא ידעו איש:
@41 **האל.** כמו האלה: **כי על כן באו.** כי הטובה הזאת תעשו לכבודי על אשר באו בצל קורתי, תרגום בטלל שרותי, תרגום של קורה שרותא:
@42 **ויאמרו גש הלאה.** קרב להלאה, כלומר התקרב לצדדין והתרחק ממנו, וכן כל הלאה שבמקרא לשון רחוק, כמו (במדבר יז ב) זרה הלאה, (ש''א כ כב) הנה החצים ממך והלאה. גש הלאה המשך להלן, בלשון לע''ז טרי''י טי''י ד''י נו''ש [משוך את עצמך ממנו], ודבר נזיפה הוא לומר אין אנו חוששין לך, ודומה לו (ישעיה סה ה) קרב אליך אל תגש בי, וכן (ישעיה מט כ) גשה לי ואשבה, המשך לצדדין בעבורי ואשב אצלך. אתה מליץ על האורחין, איך מלאך לבך. על שאמר להם על הבנות, אמרו לו גש הלאה, לשון נחת, ועל שהיה מליץ על האורחים אמרו האחד בא לגור, אדם נכרי יחידי אתה בינינו שבאת לגור, וישפוט שפוט ונעשית מוכיח אותנו: **הדלת.** דלת הסובבת לנעול ולפתוח:
@44 **פתח.** הוא החלל שבו נכנסין ויוצאין: **בסנורים.** מכת עורון: **מקטן ועד גדול.** הקטנים התחילו בעברה תחלה, שנאמר (פסוק ד) מנער ועד זקן, לפיכך התחילה הפרענות מהם:
@45 **עוד מי לך פה.** פשוטו של מקרא מי לך עוד בעיר הזאת חוץ מאשתך ובנותיך שבבית: **חתן ובניך ובנותיך.** אם יש לך חתן או בנים ובנות הוצא מן המקום: **ובניך.** בני בנותיך הנשואות. ומדרש אגדה עוד מאחר שעושין נבלה כזאת מי לך פתחון פה ללמד סניגוריא עליהם, שכל הלילה היה מליץ עליהם טובות, קרי ביה מי לך פה:
@47 **חתניו.** שתי בנות נשואות היו לו בעיר: **לוקחי בנותיו.** שאותן שבבית היו ארוסות להם:
@48 **ויאיצו.** כתרגומו ודחיקו, מהרוהו: **הנמצאות.** המזמנות לך בבית להצילם. ומדרש אגדה יש, וזה ישובו של מקרא: **תספה.** תהיה כלה. (דברים ב יד) עד תם כל הדור, מתרגם עד דסף כל דרא:
@49 **ויתמהמה.** כדי להציל את ממונו: **ויחזיקו.** אחד מהם היה שליח להצילו, וחברו להפוך את סדום, לכך נאמר (פסוק יז) ויאמר המלט, ולא נאמר ויאמרו:
@50 **המלט על נפשך.** דיך להציל נפשות, אל תחוס על הממון: **אל תביט אחריך.** אתה הרשעת עמהם, ובזכות אברהם אתה נצול, אינך כדאי לראות בפרענותם ואתה נצול: **בכל הככר.** ככר הירדן: **ההרה המלט.** אצל אברהם ברח, שהוא יושב בהר, שנאמר לעיל (יב ח) ויעתק משם ההרה. ואף עכשיו היה יושב שם, שנאמר (יג ג) אל המקום אשר היה שם אהלה בתחלה, ואף על פי שכתוב (שם יח) ויאהל אברם וגו' , אהלים הרבה היו לו ונמשכו עד חברון: **המלט.** לשון השמטה, וכן כל המלטה שבמקרא אישמוציי''ר [להנצל] בלע''ז וכן (ישעיה סו ז) והמליטה זכר, שנשמט העבר מן הרחם, (תהלים קכד ז) כצפור נמלטה, (ישעיה מו ב) לא יכלו מלט משא, להשמיט משא הרעי שבנקביהם:
@51 **אל נא אדני.** רבותינו אמרו שם זה קדש, שנאמר בו להחיות את נפשי, מי שיש בידו להמית ולהחיות. ותרגומו בבעו כען ה': **אל נא.** אל נא תאמר אלי להמלט ההרה: **נא.** לשון בקשה יט **פן תדבקני הרעה.** כשהייתי אצל אנשי סדום היה הקדוש ברוך הוא רואה מעשי ומעשי בני העיר, והייתי נראה צדיק וכדאי להנצל, וכשאבא אצל צדיק אני כרשע. וכן אמרה הצרפית לאליהו (מ''א יז יח) כי באת אלי להזכיר את עוני, עד שלא באת אצלי היה הקדוש ברוך הוא רואה מעשי ומעשי עמי ואני צדקת ביניהם, ומשבאת אצלי לפי מעשיך אני רשעה:
@53 **העיר הזאת קרובה.** קרובה ישיבתה נתישבה מקרוב, לפיכך לא נתמלאה סאתה עדיין. ומה היא קריבתה, מדור הפלגה שנתפלגו האנשים והתחילו להתישב איש איש במקומו, והיא היתה בשנת מות פלג, ומשם ועד כאן חמשים ושתים שנה, שפלג מת בשנת ארבעים ושמונה לאברהם. כיצד, פלג חי (לעיל יא יט) אחרי הולידו את רעו מאתים ותשע שנה, צא מהם שלשים ושתים כשנלד שרוג, ומשרוג עד שנלד נחור שלשים, הרי ששים ושתים, ומנחור עד שנלד תרח עשרים ותשע, הרי תשעים ואחת, ומשם עד שנלד אברהם שבעים, הרי מאה ששים ואחת, תן להם ארבעים ושמונה הרי מאתים ותשע, ואותה שנה היתה שנת הפלגה, וכשנחרבה סדום היה אברהם בן תשעים ותשע שנה, הרי מדור הפלגה עד כאן חמשים ושתים שנה, וצוער אחרה ישיבתה אחרי ישיבת סדום וחברותיה שנה אחת, הוא שנאמר אמלטה נא, נא בגימטריא חמשים ואחת: **הלא מצער היא.** והלא עונותיה מועטין, ויכול אתה להניחה: **ותחי נפשי.** בה, זה מדרשו. ופשוטו של מקרא הלא עיר קטנה היא, ואנשים בה מעט, אין לך להקפיד אם תניחנה ותחי נפשי בה:
@54 **גם לדבר הזה.** לא דיך שאתה נצול, אלא אף כל העיר אציל בגללך: **הפכי.** הופך אני, כמו (מח ה) עד בואי, (טז יג) אחרי רואי, (ירמיה לא יט) מדי דברי בו:
@55 **כי לא אוכל לעשות.** זהו ענשן של מלאכים, על שאמרו (פסוק יג) כי משחיתים אנחנו, ותלו הדבר בעצמן, לפיכך לא זזו משם עד שהזקקו לומר שאין הדבר ברשותן: **כי לא אוכל.** לשון יחיד, מכאן אתה למד שהאחד הופך והאחד מציל, שאין שני מלאכים נשלחים לדבר אחד: **על כן קרא שם העיר צוער.** על שם (פסוק כ) והיא מצער:
@57 **וה' המטיר.** כל מקום שנאמר וה' הוא ובית דינו: **המטיר על סדום.** בעלות השחר, כמו שנאמר לעיל (פסוק טו) וכמו השחר עלה, שעה שהלבנה עומדת ברקיע עם החמה, לפי שהיו מהם עובדין לחמה ומהם ללבנה, אמר הקדוש ברוך הוא אם אפרע מהם ביום יהיו עובדי לבנה אומרים אלו היה בלילה כשהלבנה מושלת לא היינו חרבין, ואם אפרע מהם בלילה יהיו עובדי החמה אומרים אלו היה ביום כשהחמה מושלת לא היינו חרבים, לכך כתיב וכמו השחר עלה ונפרע מהם בשעה שהחמה והלבנה מושלים: **המטיר** וגו' **גפרית ואש.** בתחלה מטר ונעשה גפרית ואש: **מאת ה'.** דרך המקראות לדבר כן, כמו (ד כג) נשי למך, ולא אמר נשי. וכן אמר דוד (מ''א א לג) קחו עמכם את עבדי אדוניכם, ולא אמר עבדי, וכן אחשורוש אמר (אסתר ח ח) בשם המלך, ולא אמר בשמי. אף כאן אמר מאת ה' ולא אמר מאתו: **מן השמים.** והוא שאמר הכתוב (איוב לו לא) כי בם ידין עמים וגו' , כשבא ליסר הבריות מביא עליהם אש מן השמים כמו שעשה לסדום, וכשבא להוריד המן מן השמים לישראל (שמות טז ד) הנני ממטיר לכם לחם מן השמים:
@58 **ויהפוך את הערים** וגו' **.** ארבעתן יושבות בסלע אחד והפכן מלמעלה למטה, שנאמר (איוב כח ט) בחלמיש שלח ידו וגו' :
@59 **ותבט אשתו מאחריו.** מאחריו של לוט: **ותהי נציב מלח.** במלח חטאה ובמלח לקתה. אמר לה תני מעט מלח לאורחים הללו, אמרה לו אף המנהג הרע הזה אתה בא להנהיג במקום הזה:
@61 **קיטור.** תמור של עשן טורק''א [לפיד] בלע''ז : **כבשן.** חפירה ששורפין בה את האבנים לסיד, וכן כל כבשן שבתורה:
@62 **ויזכור אלהים את אברהם.** מהו זכירתו של אברהם על לוט, נזכר שהיה לוט יודע ששרה אשתו של אברהם, ושמע שאמר אברהם במצרים על שרה (יב יט) אחותי היא, ולא גלה הדבר, שהיה חס עליו, לפיכך חס הקדוש ברוך הוא עליו:
@63 **כי ירא לשבת בצוער.** לפי שהיתה קרובה לסדום:
@64 **אבינו זקן.** ואם לא עכשיו אימתי, שמא ימות או יפסוק מלהוליד: **ואיש אין בארץ.** סבורות היו שכל העולם נחרב כמו בדור המבול:
@66 **ותשקין** וגו' **.** יין נזדמן להן במערה להוציא מהן שני אמות: **ותשכב את אביה.** ובצעירה כתיב (פסוק לה) ותשכב עמו, צעירה לפי שלא פתחה בזנות אלא אחותה למדתה, חסך עליה הכתוב ולא פירש גנותה. אבל בכירה שפתחה בזנות פרסמה הכתוב במפורש: **ובקומה.** של בכירה נקוד, לומר הרי הוא כאלו לא נכתב, לומר שבקומה ידע ואף על פי כן לא נשמר ליל שני מלשתות (אמר רבי לוי כל מי שהוא להוט אחר בלמוס של עריות לסוף מאכילים אותו מבשרו) :
@69 **ותהרין** וגו' **.** אף על פי שאין האשה מתעברת מביאה ראשונה, אלו שלטו בעצמן והוציאו ערותן לחוץ ונתעברו מביאה ראשונה:
@70 **מואב.** זו שלא היתה צנועה פרשה שמאביה הוא, אבל צעירה קראתו בלשון נקיה, וקבלה שכר בימי משה, שנאמר בבני עמון (דבר' ב יט) אל תתגר בם כלל, ובמואב לא הזהיר אלא שלא ילחם בם, אבל לצערן התיר לו:
@72 **ויסע משם אברהם.** כשראה שחרבו הכרכים ופסקו העוברים והשבים נסע לו משם. דבר אחר להתרחק מלוט שיצא עליו שם רע שבא על בנותיו:
@73 **ויאמר אברהם.** כאן לא נטל רשות אלא על כרחה שלא בטובתה לפי שכבר לקחה לבית פרעה על ידי כן: **אל שרה אשתו.** על שרה אשתו. וכיוצא בו (ש''א ד יט) אל הלקח ארון וגו' ואל מות חמיה, שניהם בלשון על:
@75 **לא קרב אליה.** המלאך מנעו, כמו שנאמר (פסוק ו) לא נתתיך לנגע אליה: **הגוי גם צדיק תהרג.** אף אם הוא צדיק תהרגנו. שמא כך דרכך לאבד האמות חנם, כך עשית לדור המבול ולדור הפלגה, אף אני אומר שהרגתם על לא דבר, כשם שאתה אומר להרגני:
@76 **גם הוא.** לרבות עבדים וגמלים וחמרים שלה, את כלם שאלתי ואמרו לי אחיה הוא: **בתם לבבי.** שלא דמיתי לחטוא: **ובנקיון כפי.** נקי אני מן החטא שלא נגעתי בה:
@77 **ידעתי כי בתם לבבך** וגו' **.** אמת שלא דמית מתחלה לחטוא אבל נקיון כפים אין כאן: **לא נתתיך.** לא ממך היה שלא נגעת בה אלא חשכתי אני אותך מחטוא, ולא נתתי לך כח, וכן (לקמן לא ז) ולא נתנו אלהים, וכן (שופט' טו א) ולא נתנו אביה לבוא:
@78 **השב אשת האיש.** ואל תהא סבור שמא תתגנה בעיניו ולא יקבלנה או ישנאך ולא יתפלל עליך: **כי נביא הוא.** ויודע שלא נגעת בה, לפיכך ויתפלל בעדך:
@80 **מעשים אשר לא יעשו.** מכה אשר לא הרגלה לבא על בריה באה לנו על ידך, עצירת כל נקבים, של זרע ושל קטנים ורעי ואזנים וחוטם:
@82 **רק אין יראת אלהים.** אכסנאי שבא לעיר, על עסקי אכילה ושתיה שואלין אותו או על עסקי אשתו שואלין אותו אשתך היא או אחותך היא:
@83 **אחותי בת אבי היא.** ובת אב מתרת לבן נח, שאין אבות לגוי. וכדי לאמת דבריו השיבם כן. ואם תאמר והלא בת אחיו היתה, בני בנים הרי הן כבנים והרי היא בתו של תרח, וכן הוא אומר ללוט (יג ח) כי אנשים אחים אנחנו: **אך לא בת אמי.** הרן מאם אחרת היה:
@84 **ויהי כאשר התעו אותי** וגו' **.** אנקלוס תרגם מה שתרגם. ויש לישבו עוד, דבר דבור על אפניו, כשהוציאני הקדוש ברוך הוא מבית אבי להיות משוטט ונד ממקום למקום, וידעתי שאעבור במקום רשעים ואומר לה זה חסדך אשר תעשי עמדי: **כאשר התעו.** לשון רבים, ואל תתמה, כי בהרבה מקומות לשון אלהות ולשון מרות קרוי לשון רבים. (שמואל ב' ז כג) אשר הלכו אלהים, (דברים ה כג) אלהים חיים, (יהושע כד יט) אלהים קדושים הוא, וכל לשון אלהים לשון רבים. וכן (לט כ) ויקח אדוני יוסף, (דברים י יז) אדוני האדונים, (להלן מב לג) אדוני הארץ, וכן (שמות כב יד) בעליו עמו, (שםכא כט) והועד בבעליו. ואם תאמר מהו לשון התעו, כל הגולה ממקומו ואינו מישב קרוי תועה, כמו (לקמן כא יד) ותלך ותתע, (תהלים קיט קעו) תעיתי כשה אובד, (איוב לח מא) יתעו לבלי אכל, יצאו ויתעו לבקש אכלם: **אמרי לי.** עלי, וכן (לקמן כו ז) וישאלו אנשי המקום לאשתו, על אשתו. וכן (שמות יד ג) ואמר פרעה לבני ישראל, כמו על בני ישראל, (שופטים ט נד) פן יאמרו לי אשה הרגתהו:
@85 **ויתן לאברהם.** כדי שיתפייס ויתפלל עליו:
@86 **הנה ארצי לפניך.** אבל פרעה אמר לו (לעיל יב יט) הנה אשתך קח ולך, לפי שנתירא שהמצריים שטופי זמה:
@87 **ולשרה אמר.** אבימלך, לכבודה כדי לפיסה הנה עשיתי לך כבוד זה, נתתי ממון לאחיך שאמרת עליו אחי הוא, הנה הממון והכבוד הזה לך כסות עינים: **לכל אשר אתך.** יכסו עיניהם שלא יקלוך, שאלו השיבותיך ריקנית יש להם לומר לאחר שנתעלל בה החזירה, עכשיו שהצרכתי לבזבז ממון ולפייסך, יודעים יהיו שעל כרחי השיבותיך ועל ידי נס: **ואת כל.** ועם כל באי העולם: **ונכחת.** יהא לך פתחון פה להתוכח ולהראות דברים נכרים הללו. ולשון תוכחת בכל מקום ברור דברים, ובלע''ז אישפרובי''ר [לבחן] ואונקלוס תרגם בפנים אחרים, ולשון המקרא כך הוא נופל על התרגום הנה הוא לך כסות של כבוד על העינים שלי ששלטו בך ובכל אשר אתך, ועל כן תרגומו וחזית יתיך וית כל דעמיך. ויש מדרש אגדה אבל ישוב לשון המקרא פרשתי:
@88 **וילדו.** כתרגומו ואתרוחו, נפתחו נקביהם והוציאו מה שצריך לצאת והיא לידה שלהם:
@89 **בעד כל רחם.** כנגד כל פתח: **על דבר שרה.** על פי דבורה של שרה:
@90 **וה' פקד את שרה** וגו' **.** סמך פרשה זו לכאן ללמדך שכל המבקש רחמים על חברו והוא צריך לאותו דבר הוא נענה תחלה, שנאמר (לעיל כ יז) ויתפלל וגו' וסמיך ליה וה' פקד את שרה שפקד כבר קודם שרפא את אבימלך: **פקד את שרה כאשר אמר.** בהריון: **כאשר דבר.** בלידה. והיכן היא אמירה והיכן הוא דבור, אמירה (לעיל יז יט) ויאמר אלהים אבל שרה אשתך וגו' . דבור (שם טו א) היה דבר ה' אל אברם, בברית בין הבתרים, ושם נאמר (שם ד) לא יירשך זה וגו' , והביא היורש משרה: **ויעש ה' לשרה כאשר דבר.** לאברהם:
@91 **למועד אשר דבר אתו.** דמליל יתיה. את המועד אשר דבר וקבע כשאמר לו (לעיל יח יד) למועד אשוב אליך, שרט לו שריטה בכותל ואמר לו, כשתגיע חמה לשריטה זו בשנה אחרת, תלד: ( **לזקניו.** שהיה זיו אקונין שלו דומה לו:) ו **יצחק לי.** ישמח עלי. ומדרש אגדה הרבה עקרות נפקדו עמה, הרבה חולים נתרפאו בו ביום, הרבה תפלות נענו עמה, ורב שחוק היה בעולם:
@96 **מי מלל לאברהם.** לשון שבח וחשיבות, ראו מי הוא ומה הוא, שומר הבטחתו, הקדוש ברוך הוא מבטיח ועושה: **מלל.** שנה הכתוב ולא אמר דבר, גימטריה שלו מאה, כלומר לסוף מאה לאברהם: **היניקה בנים שרה.** ומהו בנים לשון רבים, ביום המשתה הביאו השרות את בניהן עמהן והיניקה אותם שהיו אומרות לא ילדה שרה אלא אסופי הביאה מן השוק:
@97 **ויגמל.** לסוף עשרים וארבעה חדש: **משתה גדול.** שהיו שם גדולי הדור, שם ועבר ואבימלך:
@98 **מצחק.** לשון עבודה זרה, כמו שנאמר (שמות לב ו) ויקומו לצחק. דבר אחר לשון גלוי עריות, כמה דתימא (להלן לט יז) לצחק בי. דבר אחר לשון רציחה כמו (ש''ב ב יד) יקומו נא הנערים וישחקו לפנינו וגו' :
@99 **עם בני** וגו' **.** מתשובת שרה כי לא יירש בן האמה הזאת עם בני אתה למד שהיה מריב עם יצחק על הירשה ואמר אני בכור ונוטל פי שנים, ויוצאים בשדה ונוטל קשתו ויורה בו חצים, כמה דתימא (משלי כו יח. יט) כמתלהלה היורה זקים וגו' ואמר הלא משחק אני: **עם בני עם יצחק.** מכיון שהוא בני אפלו אם אינו הגון כיצחק, או הגון כיצחק אפלו אם אינו בני, אין זה כדאי לירש עמו, קל וחמר עם בני עם יצחק ששתיהן בו:
@100 **על אודת בנו.** ששמע שיצא לתרבות רעה. ופשוטו על שאמרה לו לשלחו:
@101 **שמע בקולה.** למדנו שהיה אברהם טפל לשרה בנביאות:
@103 **לחם וחמת מים.** ולא כסף וזהב, לפי שהיה שונאו על שיצא לתרבות רעה: **ואת הילד.** אף הילד שם על שכמה, שהכניסה בו שרה עין רעה ואחזתו חמה ולא יכול לילך ברגליו: **ותלך ותתע.** חזרה לגלולי בית אביה:
@104 **ויכלו המים.** לפי שדרך חולים לשתות הרבה:
@105 **מנגד.** מרחוק: **כמטחוי קשת.** כשתי טיחות והוא לשון ירית חץ, בלשון משנה שהטיח באשתו, על שם שהזרע יורה כחץ. ואם תאמר היה לו לכתוב כמטחי קשת, משפט הוי''ו ליכנס לכאן, כמו (שה''ש ב) בחגוי הסלע, מגזרת (ישעיה יט יז) והיתה אדמת יהודה למצרים לחגא, ומגזרת (תהלים קז כז) יחגו וינועו כשכור, וכן (שם סה ו) קצוי ארץ, מגזרת קצה: **ותשב מנגד.** כיון שקרב למות הוסיפה להתרחק:
@106 **את קול הנער.** מכאן שיפה תפלת החולה מתפלת אחרים עליו, והיא קודמת להתקבל: **באשר הוא שם.** לפי מעשים שהוא עושה עכשיו הוא נדון ולא לפי מה שהוא עתיד לעשות, לפי שהיו מלאכי השרת מקטרגים ואומרים רבונו של עולם, מי שעתיד זרעו להמית בניך בצמא אתה מעלה לו באר. והוא משיבם עכשיו מה הוא, צדיק או רשע, אמרו לו צדיק, אמר להם לפי מעשיו של עכשיו אני דנו וזהו באשר הוא שם. והיכן המית את ישראל בצמא, כשהגלם נבוכדנצר, שנאמר (ישעיה כא יג. יד) משא בערב וגו' לקראת צמא התיו מים וגו' כשהיו מוליכין אותם אצל ערביים היו ישראל אומרים לשוביהם בבקשה מכם, הוליכונו אצל בני דודנו ישמעאל וירחמו עלינו, שנאמר (שם שם) ארחות דדנים [אל תקרי דדנים אלא דודים] ואלו יוצאים לקראתם ומביאין להם בשר ודג מלוח ונודות נפוחים, כסבורים ישראל שמלאים מים, וכשמכניסו לתוך פיו ופותחו, הרוח נכנס בגופו ומת:
@109 **רבה קשת.** יורה חצים בקשת: **קשת.** על שם האמנות כמו חמר, גמל, ציד לפיכך השי''ן מדגשת. היה יושב במדבר ומלסטם את העוברים, הוא שנאמר (לעיל טז יב) ידו בכל וגו' :
@110 **מארץ מצרים.** ממקום גדוליה, שנאמר (שם א) ולה שפחה מצרית וגו' . היינו דאמרי אנשי זרוק חוטרא לאוירא, אעיקריה קאי:
@111 **אלהים עמך.** לפי שראו שיצא משכונת סדום לשלום, ועם המלכים נלחם ונפלו בידו, ונפקדה אשתו לזקוניו:
@112 **ולניני ולנכדי.** עד כאן רחמי האב על הבן: **כחסד אשר עשיתי עמך תעשה עמדי.** שאמרתי לך (לעיל כ טו) הנה ארצי לפניך:
@114 **והוכח.** נתוכח עמו על כך:
@119 **בעבור תהיה לי.** זאת: **לעדה.** לשון עדות של נקבה, כמו (להלן לא נב) ועדה המצבה: **כי חפרתי את הבאר.** מריבים היו עליה רועי אבימלך ואומרים אנחנו חפרנוה, אמרו ביניהם כל מי שיתראה על הבאר ויעלו המים לקראתו שלו היא, ועלו לקראת אברהם:
@122 **אשל.** רב ושמואל, חד אמר פרדס להביא ממנו פרות לאורחים בסעודה, וחד אמר פנדק לאכסניא ובו כל מיני פרות. ומצינו לשון נטיעה באהלים, שנאמר (דניאל יא מה) ויטע אהלי אפדנו: **ויקרא שם** וגו' **.** על ידי אותו אשל נקרא שמו של הקדוש ברוך הוא אלוה לכל העולם. לאחר שאוכלים ושותים אומר להם ברכו למי שאכלתם משלו, סבורים אתם שמשלי אכלתם, משל מי שאמר והיה העולם אכלתם:
@123 **ימים רבים.** מרבים על של חברון, בחברון עשה עשרים וחמש שנה וכאן עשרים ושש. שהרי בן שבעים וחמש שנה היה בצאתו מחרן, אותה שנה (לעיל יג יח) ויבא וישב באלוני ממרא, שלא מצינו קודם לכן שנתישב אלא שם, שבכל מקומותיו היה כאורח חונה ונוסע והולך, שנאמר (שם יב ו) ויעבור אברם, (שם ח) ויעתק משם, (שם י) ויהי רעב בארץ, וירד אברם מצרימה, ובמצרים לא עשה אלא שלשה חדשים שהרי שלחו פרעה, מיד (שם יג ג) וילך למסעיו, עד (לעיל יג יח) ויבא וישב באלוני ממרא אשר בחברון, שם ישב עד שנהפכה סדום, מיד (שם כ א) ויסע משם אברהם מפני בושה של לוט ובא לארץ פלשתים, ובן תשעים ותשע שנה היה, שהרי בשלישי למילתו באו אצלו המלאכים, הרי עשרים וחמש שנה וכאן כתיב ימים רבים, מרבים על הראשונים, ולא בא הכתוב לסתום אלא לפרש, ואם היו מרבים עליהם שתי שנים או יותר היה מפרשם, ועל כרחך אינם יתרים יותר משנה הרי עשרים ושש שנה, מיד יצא משם וחזר לחברון, ואותה שנה קדמה לפני עקידתו של יצחק שתים עשרה שנים, כך שנויה בסדר עולם (פרק א) :
@124 **אחר הדברים האלה.** יש מרבותינו אומרים אחר דבריו של שטן, שהיה מקטרג ואומר מכל סעודה שעשה אברהם לא הקריב לפניך פר אחד או איל אחד, אמר לו כלום עשה אלא בשביל בנו, אלו הייתי אומר לו זבח אותו לפני לא היה מעכב. ויש אומרים אחר דבריו של ישמעאל שהיה מתפאר על יצחק שמל בן שלש עשרה שנה ולא מחה, אמר לו יצחק באבר אחד אתה מיראני, אלו אמר לי הקדוש ברוך הוא זבח עצמך לפני לא הייתי מעכב: **הנני.** כך היא עניתם של חסידים, לשון ענוה הוא ולשון זמון:
@125 **קח נא.** אין נא אלא לשון בקשה, אמר לו בבקשה ממך עמוד לי בזה הנסיון, שלא יאמרו הראשונות לא היה בהן ממש: **את בנך.** אמר לו שני בנים יש לי, אמר לו את יחידך, אמר לו זה יחיד לאמו וזה יחיד לאמו, אמר לו אשר אהבת, אמר לו שניהם אני אוהב, אמר לו את יצחק. ולמה לא גלה לו מתחלה, שלא לערבבו פתאום, ותזוח דעתו עליו ותטרף, וכדי לחבב עליו את המצוה ולתן לו שכר על כל דבור ודבור: **ארץ המוריה.** ירושלים, וכן בדברי הימים (ב' ג א) לבנות את בית ה' בירושלים בהר המוריה. ורבותינו פרשו על שם שמשם הוראה יוצאה לישראל. ואונקלוס תרגמו על שם עבודת הקטורת שיש בה מור נרד ושאר בשמים: **והעלהו.** לא אמר לו שחטהו, לפי שלא היה חפץ הקדוש ברוך הוא לשחטו אלא שיעלהו להר לעשותו עולה, ומשהעלהו אמר לו הורידהו: **אחד ההרים.** הקדוש ברוך הוא מתהא הצדיקים ואחר כך מגלה להם, וכל זה כדי להרבות שכרן, וכן (לעיל יב א) אל הארץ אשר אראך, וכן ביונה (ג ב) וקרא אליה את הקריאה:
@126 **וישכם.** נזדרז למצוה: **ויחבש.** הוא בעצמו ולא צוה לאחד מעבדיו, שהאהבה מקלקלת השורה: **את שני נעריו.** ישמעאל ואליעזר, שאין אדם חשוב רשאי לצאת לדרך בלא שני אנשים, שאם יצטרך האחד לנקביו ויתרחק יהיה השני עמו: **ויבקע.** תרגומו וצלח, כמו (ש''ב יט יח) וצלחו הירדן, לשון בקוע (י''ג בקוע) פינדר''א בלע''ז [לחטוב]:
@127 **ביום השלישי.** למה אחר מלהראותו מיד, כדי שלא יאמרו הממו וערבבו פתאום וטרד דעתו, ואלו היה לו שהות להמלך אל לבו לא היה עושה: **וירא את המקום.** ראה ענן קשור על ההר:
@128 **עד כה.** כלומר דרך מועט למקום אשר לפנינו. ומדרש אגדה אראה היכן הוא מה שאמר לי המקום (לעיל טו ה) כה יהיה זרעך: **ונשובה.** נתנבא שישובו שניהם:
@129 **המאכלת.** סכין, על שם שאוכלת את הבשר, כמה דתימא (דברים לב מב) וחרבי תאכל בשר, ושמכשרת בשר לאכילה. דבר אחר זאת נקראת מאכלת, על שם שישראל אוכלים מתן שכרה: **וילכו שניהם יחדו.** אברהם שהיה יודע שהולך לשחוט את בנו היה הולך ברצון ושמחה כיצחק שלא היה מרגיש בדבר:
@131 **יראה לו השה.** כלומר יראה ויבחר לו השה, ואם אין שה, לעולה בני. ואף על פי שהבין יצחק שהוא הולך לשחט, וילכו שניהם יחדו בלב שוה:
@132 **ויעקד.** ידיו ורגליו מאחוריו, הידים והרגלים ביחד היא עקידה, והוא לשון (להלן ל לט) עקדים, שהיו קרסליהם לבנים, מקום שעוקדין אותן בו היה נכר:
@134 **אברהם אברהם.** לשון חבה הוא שכופל את שמו:
@135 **אל תשלח.** לשחוט, אמר לו אם כן לחנם באתי לכאן, אעשה בו חבלה ואוציא ממנו מעט דם, אמר לו אל תעש לו מאומה, אל תעש בו מום: **כי עתה ידעתי.** אמר רבי אבא אמר לו אברהם אפרש לפניך את שיחתי, אתמול אמרת לי (לעיל כא יב) כי ביצחק יקרא לך זרע, וחזרת ואמרת (שם כב ב) קח נא את בנך, עכשיו אתה אומר לי אל תשלח ידך אל הנער. אמר לו הקדוש ברוך הוא (תהלים פט לה) לא אחלל בריתי ומוצא שפתי לא אשנה, כשאמרתי לך קח, מוצא שפתי לא אשנה, לא אמרתי לך שחטהו אלא העלהו, אסקתיה, אחתיה: **כי עתה ידעתי.** מעתה יש לי מה להשיב לשטן ולאומות התמהים מה היא חבתי אצלך, יש לי פתחון פה עכשיו שרואים כי ירא אלהים אתה:
@136 **והנה איל.** מוכן היה לכך מששת ימי בראשית: **אחר.** אחרי שאמר לו המלאך (לעיל פסוק יב) אל תשלח ידך, ראהו כשהוא נאחז, והוא שמתרגמינן וזקף אברהם עינוהי בתר אלין: **בסבך.** אילן: **בקרניו.** שהיה רץ אצל אברהם והשטן סובכו ומערבבו באילנות כדי לעכבו: **תחת בנו.** מאחר שכתוב ויעלהו לעולה, לא חסר המקרא כלום, מהו תחת בנו, על כל עבודה שעשה ממנו היה מתפלל ואומר יהי רצון שתהא זו כאלו היא עשויה בבני, כאלו בני שחוט, כאלו דמו זרוק, כאלו הוא מפשט, כאלו הוא נקטר ונעשה דשן:
@137 **ה' יראה.** פשוטו כתרגומו, ה' יבחר ויראה לו את המקום הזה להשרות בו שכינתו ולהקריב כאן קרבנות: **אשר יאמר היום.** שיאמרו לימי הדורות עליו בהר זה יראה הקדוש ברוך הוא לעמו: **היום.** הימים העתידין, כמו עד היום הזה שבכל המקרא, שכל הדורות הבאים הקוראים את המקרא הזה אומרים עד היום הזה על היום שעומדים בו. ומדרש אגדה ה' יראה עקידה זו לסלוח לישראל בכל שנה ולהצילם מן הפרענות, כדי שיאמר היום הזה בכל הדורות הבאים בהר ה' יראה, אפרו של יצחק צבור ועומד לכפרה:
@140 **ברך אברכך.** אחת לאב ואחת לבן: **והרבה ארבה.** אחת לאב ואחת לבן:
@142 **וישב אברהם בבאר שבע.** לא ישיבה ממש, שהרי בחברון היה יושב שתים עשרה שנים לפני עקידתו של יצחק, יצא מבאר שבע והלך לו לחברון, כמו שנאמר (לעיל כא לד) ויגר אברהם בארץ פלשתים ימים רבים, מרבים משל חברון הראשונים, והם עשרים ושש שנה כמו שפרשנו למעלה (כא לד) :
@143 **אחרי הדברים האלה ויגד** וגו' **.** בשובו מהר המוריה היה אברהם מהרהר ואומר אלו היה בני שחוט כבר היה הולך בלא בנים, היה לי להשיאו אשה מבנות ענר אשכול וממרא, בשרו הקדוש ברוך הוא שנלדה רבקה בת זוגו, וזהו אחרי הדברים האלה הרהורי דברים שהיו על ידי עקידה: **גם היא.** אף היא השותה משפחותיה למשפחות אברהם שתים עשרה, מה אברהם שנים עשר שבטים שיצאו מיעקב, שמונה בני הגבירות וארבעה בני שפחות, אף אלו שמונה בני גבירות וארבעה בני פלגש:
@146 **ובתואל ילד את רבקה.** כל היחוסין הללו לא נכתבו אלא בשביל פסוק זה:

@1 **וירא אליו** . לשון רש"י לבקר את החולה אמר רבי חמא בר חנינא יום שלישי למילתו היה ובא הקב"ה ושאל בו והנה שלשה אנשים המלאכים שבאו אליו בדמות אנשים שלשה אחד לבשר את שרה ואחד לרפאות את אברהם ואחד להפוך את סדום ורפאל שריפא את אברהם הלך משם להציל את לוט שאין זה שתי שליחות כי היה במקום אחר ונצטווה בו אחר כן או ששתיהן להצלה ויאכלו נראו כמי שאכלו ובספר מורה הנבוכים (ב מב) נאמר כי הפרשה כלל ופרט אמר הכתוב תחלה כי נראה אליו השם במראות הנבואה ואיך היתה המראה הזאת כי נשא עיניו במראה והנה ג' אנשים נצבים עליו ויאמר אם נא מצאתי חן בעיניך זה ספור מה שאמר במראה הנבואה לאחד מהם הגדול שבהם ואם במראה לא נראו אליו רק אנשים אוכלים בשר איך אמר "וירא אליו ה'" כי הנה לא נראה לו השם לא במראה ולא במחשבה וככה לא נמצא בכל הנבואות והנה לדבריו לא לשה שרה עוגות ולא עשה אברהם בן בקר וגם לא צחקה שרה רק הכל מראה ואם כן בא החלום הזה ברוב ענין כחלומות השקר כי מה תועלת להראות לו כל זה וכן אמר (שם) בענין "ויאבק איש עמו" (להלן לב כה) שהכל מראה הנבואה ולא ידעתי למה היה צולע על ירכו בהקיץ ולמה אמר (להלן לב לא) כי ראיתי אלהים פנים אל פנים ותנצל נפשי כי הנביאים לא יפחדו שימותו מפני מראות הנבואה וכבר ראה מראה גדולה ונכבדת מזאת כי גם את השם הנכבד ראה פעמים רבות במראה הנבואה (עיין להלן כח יג לא ג) והנה לפי דעתו זאת יצטרך לומר כן בענין לוט כי לא באו המלאכים אל ביתו ולא אפה להם מצות ויאכלו אבל הכל היה מראה ואם יעלה את לוט למעלת מראה הנבואה איך יהיו אנשי סדום הרעים והחטאים נביאים כי מי הגיד להם שבאו אנשים אל ביתו ואם הכל מראות נבואתו של לוט יהיה "ויאיצו המלאכים וגו' קום קח את אשתך" "ויאמר המלט על נפשך" (להלן יט טו יז) ו"הנה נשאתי פניך" (שם כא) וכל הפרשה כלה מראה וישאר לוט בסדום אבל יחשוב שהיו המעשים נעשים מאליהם והמאמרים בכל דבר ודבר מראה ואלה דברים סותרים הכתוב אסור לשומעם אף כי להאמין בהם ובאמת כי כל מקום שהוזכר בכתוב ראיית מלאך או דבור מלאך הוא במראה או בחלום כי ההרגשים לא ישיגו המלאכים אבל לא מראות הנבואה כי המשיג לראות מלאך או דיבורו איננו נביא שאין הדבר כמו שהרב גוזר (במו"נ ב לד ובהלכות יסוה"ת ז ו) כי כל נביא זולת משה רבינו נבואתו על ידי מלאך וכבר אמרו (מגילה ג) בדניאל אינהו עדיפי מיניה דאינהו נביאי ואיהו לאו נביא וכן לא נכתב ספרו עם ספר הנביאים מפני שהיה עניינו עם גבריאל אף על פי שהיה נראה אליו ומדבר עמו בהקיץ כמו שנאמר במראה של בית שני ועוד אני מדבר בתפלה והאיש גבריאל (דניאל ט כא) וכן המראה של קץ הגאולה (שם י ד) בהקיץ היתה בלכתו עם חביריו על יד הנהר ואין הגר המצרית מכלל הנביאות וברור הוא גם כן שלא היה ענינה בת קול כמו שאמר הרב (במו"נ שם) והכתוב חלק נבואת משה רבינו מנבואת האבות כמה שנאמר (שמות ו ג) וארא אל אברהם אל יצחק ואל יעקב באל שדי וזה שם משמות הקדש לבורא איננו כנוי למלאך ורבותינו עוד למדו על החילוק שביניהם ואמרו (ויק"ר א יד) מה בין משה לכל הנביאים רבנן אמרי כל הנביאים ראו מתוך אספקלריא שאינה מצוחצחת הדא הוא דכתיב (הושע יב יא) ואנכי חזון הרביתי וביד הנביאים אדמה ומשה ראה מתוך אספקלריא מצוחצחת הדא הוא דכתיב (במדבר יב ח) ותמונת ה' יביט כמו שהוא מפורש בויקרא רבה (שם) ומקומות אחרים (יבמות מט) ולא נתנו בשום מקום נבואתם למלאך ואל תשומם בעבור שכתוב (מלכים א יג יח) גם אני נביא כמוך ומלאך דבר אלי בדבר ה' לאמר כי פירושו גם אני נביא כמוך ויודע אני שהמלאך שדבר אלי בדבר ה' הוא וזו מדרגה ממדרגות הנבואה כאשר אמר איש האלהים כי כן צוה אותי בדבר ה' (שם יג ט) ואמר כי דבר אלי בדבר ה' (שם יג יז) וכבר אמרו רבותינו (במד"ר כ ג) בענין בלעם שאמר ועתה אם רע בעיניך אשובה לי (במדבר כב לד) אני לא הלכתי עד שאמר לי הקב"ה קום לך אתם (שם שם כ) ואתה אומר שאחזור כך הוא אומנותו לא כך אמר לאברהם להקריב את בנו ואחר כך ויקרא מלאך ה' אל אברהם ויאמר אל תשלח ידך אל הנער (להלן כב יב) למוד הוא לומר דבר ומלאך מחזירו וכו' הנה החכמים מתעוררים לומר שאין הנבואה בדבור הראשון שהזכיר בו השם שוה לדיבור השני שאמר בו שהוא על ידי מלאך אלא שהוא דרך בנביאים שיצוה בנבואה ויבטל הצואה במלאך כי הנביא יודע כי דבר ה' הוא ובתחלת ויקרא רבה (א ט) אמרו ויקרא אל משה לא כאברהם באברהם כתוב ויקרא מלאך ה' אל אברהם שנית מן השמים (להלן כב טו) המלאך קורא והדבור מדבר ברם הכא אמר הקב"ה אני הוא הקורא ואני הוא המדבר כלומר שלא היה אברהם משיג הנבואה עד הכינו נפשו בתחלה להשגת מלאך ויעלה מן המדרגה ההיא למעלת דבור הנבואה אבל משה מוכן לנבואה בכל עת הנה בכל מקום יתעוררו החכמים להודיענו כי ראיית המלאך איננה נבואה ואין הרואים מלאכים והמדברים עמם מכלל הנביאים כאשר הזכרתי בדניאל אבל היא מראה תקרא "גלוי עינים" כמו ויגל השם את עיני בלעם וירא את מלאך ה' (במדבר כב לא) וכן ויתפלל אלישע ויאמר ה' פקח נא את עיניו ויראה (מלכים ב ו יז) אבל במקום אשר יזכיר המלאכים בשם "אנשים" כענין הפרשה הזאת ופרשת לוט וכן ויאבק איש עמו (להלן לב כה) וכן וימצאהו איש (שם לז טו) על דעת רבותינו (תנחומא וישב ב) הוא כבוד נברא במלאכים יקרא אצל היודעים "מלבוש" יושג לעיני בשר בזכי הנפשות כחסידים ובני הנביאים ולא אוכל לפרש והמקום אשר תמצא בו ראיית ה' ודבור מלאך או ראיית מלאך ודבור ה' ככתוב בדברי משה בתחילת נבואתו (שמות ג ב-ד) ובדברי זכריה (ג א-ב) עוד אגלה בו דברי אלהים חיים ברמיזות (עיין שמות ג ב) וענין ויאכלו אמרו חכמים (ב"ר מח יד) ראשון ראשון מסתלק וענין ההסתלקות תבין אותו מדבר מנוח אם תזכה אליו והנה פירוש הפרשה הזאת אחרי שאמר כי בעצם היום הזה נמול אברהם (לעיל יז כו) אמר שנראה אליו השם בהיותו חולה במילתו יושב ומתקרר בפתח אהלו מפני חום היום אשר יחלישנו והזכיר זה להודיע שלא היה מתכוין לנבואה לא נופל על פניו ולא מתפלל ואף על פי כן באה אליו המראה הזאת
@1 "באלוני ממרא" - להודיע המקום אשר בו נימול וזה גילוי השכינה אליו למעלה וכבוד לו כענין שבא במשכן ויצאו ויברכו את העם וירא כבוד ה' אל כל העם (ויקרא ט כג) כי מפני השתדלותם במצות המשכן זכו לראיית השכינה ואין גלוי השכינה כאן וכאן לצוות להם מצוה או לדבור כלל אלא גמול המצוה הנעשית כבר ולהודיע כי רצה האלהים את מעשיהם כענין שנאמר (תהלים יז טו) אני בצדק אחזה פניך אשבעה בהקיץ תמונתך וכן ביעקב אמר (להלן לב ב) ויפגעו בו מלאכי אלהים ואין שם דבור ולא שחדשו בו דבר רק שזכה לראיית מלאכי עליון וידע כי מעשיו רצויים וכן היה לאברהם בראיית השכינה זכות והבטחה וכן אמרו (מכילתא שירתא ג) ביורדי הים שאמרו "זה אלי ואנוהו" ראתה שפחה על הים מה שלא ראה יחזקאל הנביא זכות להם בעת הנס הגדול שהאמינו בה' ובמשה עבדו ופעמים יבא בשעת הקצף ויאמרו כל העדה לרגום אותם באבנים וכבוד ה' נראה באהל מועד אל כל בני ישראל (במדבר יד י) ויהיה זה להגין על עבדיו הצדיקים ולכבודם ואל תחוש להפסק הפרשה כי הענין מחובר ולכן אמר "וירא אליו" ולא אמר "וירא ה' אל אברהם" אבל בפרשה רצה לסדר כבוד הנעשה לו בעת שעשה המילה ואמר כי נגלית עליו השכינה ושלח אליו מלאכיו לבשר את אשתו וגם להציל לוט אחיו בעבורו כי אברהם נתבשר בבן מפי השכינה כבר ושרה מפי המלאך שדבר עם אברהם כדי שתשמע שרה כמו שאמר ושרה שומעת וזו כוונתם שאמרו (סוטה יד) לבקר את החולה שלא היה לדבור אלא לכבוד לו ועוד אמרו (ב"ר מח ד) מזבח אדמה תעשה לי (שמות כ כד) ומה אם זה שבנה מזבח לשמי הריני נגלה עליו ומברכו אברהם שמל עצמו לשמי על אחת כמה וכמה ושמא כיוונו עוד בזה לומר שהיה לו במראה השכינה רפוי למחלת המילה כי כן ראוי להיות כדכתיב (משלי טז טו) באור פני מלך חיים וטעם נצבים עליו שהיו עומדים לנגדו מסתכלים כלשון הנצב על הקוצרים (רות ב ה) משרי הנצבים (מלכים א ה ל) ולפי שהוא יושב והם היו עומדים ורואים בו אמר "עליו" וזה טעם וירא וירץ לקראתם כי כאשר ראה אותם עומדים נגדו ולא היו הולכים לדרכם רץ לקראתם להביאם אל ביתו וטעם מפתח האהל להגיד שהיה עדיין יושב שם אחרי הסתלק ממנו מראה השכינה ויתכן שיהיה "עליו" על האהל שהיו קרובים אליו מן הצד האחר שלא כנגד הפתח והיו שם נצבים ולא היו מתקרבין אל אברהם כטעם חונים על הים (שמות יד ט)
@3 **אדני אם נא מצאתי חן בעיניך** . מצינו אותו בספרים קמוץ והנה קראם בשם רבם באל"ף דל"ת כי הכיר בהם שהם מלאכי עליון כאשר יקראו אלהים ואלים ולכן השתחוה להם ארצה
@3 "אל נא תעבור מעל עבדך" - עם כל אחד ידבר כדרך כל התורה ושמרתם את (כל) חקתי (ועשיתם אותם) ערות אביך וערות אמך לא תגלה (ויקרא יח ה ז) ובקצרכם את קציר ארצכם לא תכלה (שם יט ט) ובקשתם משם את ה' אלהיך ומצאת כי תדרשנו בכל לבבך ובכל נפשך (דברים ד כט) ורוב משנה התורה כן והפך מזה ראה אנכי נותן לפניכם היום (שם יא כו) ורבותינו אמרו (ב"ר מח ו) לגדול שבהם אמר וגם זה יתכן שאמר לגדול אל נא תעבור ואתה ורעיך אשר ישארו עמך תרחצו רגליכם והנכון בעיני שקרא את כולם אדונים ופנה אל כל אחד ואחד לראשון אמר אם נא מצאתי חן בעיניך אל נא תעבור וכן אמר לשני וכן אמר לשלישי לכל אחד בפני עצמו יתחנן אם נא מצאתי חן בעיניך אל נא תעבור מעל עבדך ויוקח נא מעט מים ורחצו רגליכם כלכם וזה דרך מוסר וכבוד מרוב חפצו להתנדב עמהם והנה הכיר בהם שהם עוברי דרך ואין חפצם ללון שם ולכן לא בקש מהם רק שיוקח מעט מים לרחוץ רגליהם מעט מפני החום לתת מים קרים על נפש עיפה וישענו תחת העץ לרוח היום לא יבואו באהל ובמשכן
@5 **כי על כן עברתם** . כי אחרי שדרככם עלי איננו נכון שלא תנוחו מעט אצלי כן תעשה כאשר דברת דרך מוסר שבפת לחם די לשון רבי אברהם או יאמר כן תעשה לנו להשען תחת העץ ולעבור מיד כי שלוחים אנחנו ואל תעכבנו לבא באהל או ללון עמך
@6 **קמח סלת** . סלת לעוגות קמח לעמילן של טבחים לכסות את הקדרה לשאוב את הזוהמא לשון רש"י וכך הוא בבראשית רבה (מח יב) ושם פירשו שהיו שלש סאים לכל אחד ולא ידענו למה הרבה בלחם כל כך לשלשה אנשים אולי ידע הסתלקות המאכל ראשון ראשון והוא כמרבה עולות למזבח או שסעדו גדולי ביתו עמהם לכבודם ועל דרך הפשט מהרי שלש סאים קמח לעשות מהן סלת והנה הוציאה מכל השלש סאין סלת נקיה מעט
@7 **וטעם ואל הבקר רץ אברהם** . להגיד רוב חשקו בנדיבות כי האדם הגדול אשר היו בביתו שמונה עשר ושלש מאות איש שולף חרב והוא זקן מאד וחלוש במילתו הלך הוא בעצמו אל אהל שרה לזרז אותה בעשיית הלחם ואחרי כן רץ אל מקום הבקר לבקר משם בן בקר רך וטוב לעשות לאורחיו ולא עשה כל זה על יד אחד ממשרתיו העומדים לפניו
@10 **שוב אשוב אליך כעת חיה** . לשון רש"י לא בשרו המלאך שישוב אליו אלא בשליחותו של מקום אמר לו כמו ויאמר לה מלאך ה' הרבה ארבה את זרעך (לעיל טז י) והוא אין בידו להרבות אלא בשליחותו של מקום אמר לו אף כאן בשליחותו של מקום אמר לו והוצרך הרב לאמר כן מפני שהקב"ה אמר לו בכאן למועד אשוב אליך ובין במלאך או בהקב"ה לא מצינו ששב אליו למועדו אולי נכלל בלשון וה' פקד את שרה כאשר אמר ויעש ה' לשרה כאשר דבר (להלן כא א) ורבי אברהם אמר (להלן כא ב) כי "ויאמר ה' אל אברהם" הוא דבר המלאך בשם שולחו ושב אליו למועד אשר דבר אתו ואם לא נכתב והנכון בעיני שהוא מן "לתשובת השנה" ( יא א) יאמר כי שוב אשוב אליך עת כעת הזאת שתהיו בו חיים ויהיה בן לשרה אשתך וזהו כאשר נאמר לאברהם (לעיל יז כא) למועד הזה בשנה האחרת ויהיה "אשוב" כמו ושב ה' אלהיך ושב וקבצך (דברים ל ג)
@11 **באים בימים** . האדם בימי בחורותיו יקרא "עומד בימים" ויקראו "ימיו" כי הם שלו כלשון את מספר ימיך אמלא (שמות כג כו) אבל כאשר יזקין ויחיה ימים רבים מרוב בני האדם בדורו יקרא "בא בימים" מפני שהוא כבא בארץ אחרת נוסע מעיר ובא אל עיר מיום אל יום חדל להיות לשרה אורח כנשים הוא הזמן להריון כי אחרי הפסק האורח מחמת זקנה לא תהרינה
@13 **ואני זקנתי** . הוא פירוש אחרי בלותי ודבריו אמת אך מפני השלום לא רצה לגלות מה שאמרה "ואדוני זקן" כי היה ראוי שיאמר "ואני ואדוני זקנים" כי שרה בשניהם תצחק
@14 **היפלא מה' דבר** . אם דבר נפלא ורחוק הוא שיהיה מאת ה' ככה כלשון כי ממך הכל ומידך נתנו לך (דהי"א כט יד) ודומה לזה מאשר שמנה לחמו (להלן מט כ) מאת אשר תבא לחם שמנה ואונקלוס תרגם היתכסי עשאו כלשון כי יפלא ממך דבר למשפט (דברים יז ח) ואם כן יש בו סוד נעלם ולשון רש"י היפלא היתכסי וכי שום דבר מופלא ומכוסה ממני מלעשות כרצוני הרכיב בו שני ענינים
@15 **ותכחש שרה לאמר** . אני תמה בנביאה הצדקת איך תכחש באשר אמר השם לנביא וגם למה לא האמינה לדברי מלאכי אלהים והנראה בעיני כי המלאכים האלה הנראים כאנשים באו אל אברהם והוא בחכמתו הכיר בהם ובשר אותו שוב אשוב אליך ולשרה בן ושרה שומעת ולא ידעה כי מלאכי עליון הם כענין באשת מנוח (שופטים יג ו) ואולי לא ראתה אותם כלל
@15 "ותצחק בקרבה" - ללעג כמו יושב בשמים ישחק ה' ילעג למו (תהלים ב ד) כי השחוק לשמחה הוא בפה אז ימלא שחוק פינו (שם קכו ב) אבל השחוק בלב לא יאמר בשמחה והקב"ה האשים אותה לאברהם למה היה הדבר נמנע בעיניה וראוי לה שתאמין או שתאמר "אמן כן יעשה ה'" והנה אברהם אמר אליה למה צחקת היפלא מה' דבר ולא פירש אליה כי השם גילה אליו סודה והיא מפני יראתו של אברהם תכחש כי חשבה שאברהם בהכרת פניה יאמר כן או מפני ששתקה ולא נתנה שבח והודאה בדבר ולא שמחה והוא אמר לא כי צחקת אז הבינה כי בנבואה נאמר לו כן ושתקה ולא ענתה אותו דבר וראוי שנאמר עוד כי אברהם לא גילה לה הנאמר לו מתחילה (לעיל יז יט) אבל שרה אשתך יולדת לך בן אולי המתין עד שלוח השם אליה הבשורה ביום מחר כי ידע כי לא יעשה ה' אלהים דבר כי אם גלה סודו אל עבדיו הנביאים (עמוס ג ז) או מרוב זריזותו במצות היה טרוד במילתו ומילת עם רב אשר בביתו ואחר כן בחולשתו ישב לו פתח האהל והמלאכים באו טרם שהגיד לה דבר
@17 **וה' אמר** . אל צבא השמים העומדים עליו או אל המלאכים השלוחים ויתכן שהוא המחשבה כי חשב שלא יתכסה ממנו מפני הטעמים הללו וכן ואני אמרתי בדמי ימי (ישעיהו לח י) וכן ויאמר להכות את דוד ( כא טז) וכן כל אמירה עם הלב מחשבה
@18 **ואברהם היו יהיה** . מדרש אגדה זכר צדיק לברכה הואיל והזכירו ברכו ופשוטו של מקרא וכי ממנו אני מעלים והלא חביב לפני להיות לגוי עצום לשון רש"י והנכון כי השם יתברך דבר בכבוד אברהם אמר הנה הוא עתיד להיות לגוי גדול ועצום ויהיה זכרו בזרעו ובכל גויי הארץ לברכה לכן לא אכסה ממנו כי יאמרו הדורות הבאים איך כיסה ממנו או איך נתאכזר הצדיק על שכיניו החונים עליו ולא ריחם ולא התפלל עליהם כלל והגלוי אליו טוב ויפה כי ידעתי בו שהוא מכיר ויודע שאני ה' אוהב צדקה ומשפט כלומר שאני עושה משפט רק בצדקה ולכך יצוה את בניו וביתו אחריו לאחוז דרכי והנה אם בדרך צדקה ומשפט יפטרו יתפלל לפני להניחם וטוב הדבר ואם חייבין הם לגמרי גם הוא יחפוץ במשפטם ולכן ראוי שיבא בסוד ה'
@19 **כי ידעתיו למען אשר יצוה** . לשון רש"י ארי ידעתיניה כתרגומו לשון חבה כמו מודע לאישה (רות ב א) ואדעך (שמות לג יז) אמנם עיקר כולם לשון ידיעה שהמחבב את האדם ומקרבו אצלו יודעו ומכירו ואם תפרשהו יודע אני בו שיצוה את בניו אין "למען" נופל על הלשון ויתכן שיהיה "ידעתיו" גדלתיו ורוממתיו בעבור אשר יצוה את בניו אחריו לעשות את הישר לפני ולכך אשימנו לגוי גדול ועצום שיעבדוני וכמוהו ידעתיך בשם (שמות לג יב) מה אדם ותדעהו (תהלים קמד ג) או יאמר "ידעתיו שיצוה" וכן למען ינוח שורך וחמורך (שמות כג יב) שינוח והנכון בעיני שהיא ידיעה בו ממש ירמוז כי ידיעת השם שהיא השגחתו בעולם השפל היא לשמור הכללים וגם בני האדם מונחים בו למקרים עד בא עת פקודתם אבל בחסידיו ישום אליו לבו לדעת אותו בפרט להיות שמירתו דבקה בו תמיד לא תפרד הידיעה והזכירה ממנו כלל כטעם לא יגרע מצדיק עיניו (איוב לו ז) ובאו מזה פסוקים רבים כדכתיב (תהלים לג יח) הנה עין ה' אל יראיו וזולת זה
@20 **ויאמר ה' זעקת סדום ועמורה** . לשון רש"י ויאמר ה' אל אברהם שעשה כאשר אמר שלא יכסה ממנו ואמר רבי אברהם כי נכנס פסוק "ויפנו משם האנשים" בנתים להודיע כי בעת שבאו לסדום אז אמר השם לאברהם "זעקת סדום ועמורה כי רבה" וכן דעת כל המפרשים כי עם אברהם ידבר ולפי זה הנכון בפסוק "ויפנו משם האנשים" לומר כי כאשר אמר השם לאברהם בנסוע האנשים ממנו "זעקת סדום ועמורה כי רבה" עמד אברהם בתפלה ותחנה לפניו למחול להם ולתת לו רשות לדבר והאריך בתפלתו עד שבאו האנשים סדומה ואז נגש אברהם ואמר "האף תספה" או יהיה פירושו ששב לבאר "עודנו עומד לפני ה'" כי נגש אברהם ואמר "האף תספה" והנה האריך בתחינה לפניו בכל פעם לאמר "אל יחר אף ה'" והיה עוד מכוין דעתו בכל פעם לנבואה עד ששמע תשובה לדבריו מפיו של הקדוש ברוך הוא והאריכו כל היום בזה וילך ה' בערב כאשר כלה לדבר אל אברהם ובאו שני המלאכים סדומה
@20 "זעקת סדום ועמורה" - היא זעקת עשוקים יזעקו וישועו מזרוע רשעתם והיה ראוי שיאמר הכתוב זעקת סדום ועמורה שמעתי כי רבה או שיאמר זעקת סדום ועמורה רבה וחטאתם כבדה מאד אבל ענין הכתוב זעקת סדום ועמורה וחטאתם שגדלו מאד ארד ואראה אם כלם חטאו בהם ואם לא אדעה מי החוטאים וענין הירידה והראיה אמר רש"י בדרך הדרש לימד שלא יפסקו דיני נפשות אלא בראיה ועל דרך הפשט מפני שרצה הקב"ה לגלות לאברהם עניין סדום ולהודיעו כי אין בהם עושה טוב אמר אליו זעקת סדום ועמורה כי רבה ארד לראות כלומר באתי לשפוט אם חטאו אעשה בהם כלה ואם לא אדעה מה אעשה בהם ופקדתי בשבט פשעם ובנגעים עונם הודיעו כי אין עוד נגמר דינם וכי עתה יפקוד עונם וישפוט אותם וזה כלשון ה' משמים השקיף על בני אדם לראות היש משכיל דורש את אלהים הכל סר יחדיו נאלחו (תהלים יד ב ג) ורבי אברהם אמר בו סוד מילדי נכרים יספיקו בו ואני ארמוז לך דעת מקבלי האמת דרשו רבותינו (ירושלמי תענית פ"ב) בפסוק כי הנה ה' יוצא ממקומו וירד ודרך על במתי ארץ (מיכה א ג) יוצא ובא לו ממדה למדה יוצא ממדת רחמים ובא לו למדת הדין וכן הענין הזה ויאמר ה' אל לבו זעקת סדום ועמורה כי רבה ארד ממדת רחמים אל מדת הדין (זהר קה) ואראה ברחמים אם כצעקתה הבאה אלי במדת הדין עשו כלה (שם קו) ואם לא אדעה וארחם כדרך וידע אלהים (שמות ב כה) ואחר שסיפר הכתוב דעת העליון חזר אל הענין הראשון וסיפר במעשה כי האנשים אשר השקיפו על פני סדום ללכת שמה ושלחם אברהם הגיעו שמה ואברהם מעת הפרדם ממנו ועד הגיעם שם עודנו עומד לפניו כי קראו והגיד לו כי המלאכים הם השלוחים האלה להשחית המקום כאשר אמר ולא הוצרך לפרש מתי עמד לפניו כי מעת שאמר "המכסה אני מאברהם" נודע שהגיד לו
@23 **ויגש אברהם ויאמר האף תספה צדיק עם רשע** . אפו של הקדוש ברוך הוא היא מדת דינו וחשב אברהם שהיא תספה צדיק עם רשע לא ידע מחשבות ה' אשר חשב עליהם ברחמיו כאשר פירשתי ולכן אמר כי הגון וטוב הוא שישא לכל המקום למען חמשים הצדיקים אבל לא יתכן גם במדת הדין להמית צדיק עם רשע שאם כן יהיה כצדיק כרשע ויאמרו שוא עבוד אלהים וכל שכן במדת רחמים שהוא שופט כל הארץ והוא העושה משפט כענין ויגבה ה' צבאות במשפט (ישעיהו ה טז) ואמרנו (ברכות יב) המלך המשפט וזהו ענין הכפל חלילה לך והקב"ה הודה שישא לכל המקום בעבורם כי במדת רחמים יתנהג עמהם ומה שיודיע אליך כל הענין היות ויאמר ה' כתוב יו"ד ה"א וכל אשר הזכיר אברהם אל"ף דל"ת והנה זה מבואר
@24 **חמשים צדיקים** . כתב רש"י עשרה לכל כרך וכרך התשחית בחמשה תשעה לכל כרך וכרך ואתה צדיקו של עולם תצטרף עמהם אולי ימצאון שם ארבעים וימלטו ארבעה כרכים וכן שלשים יצילו שלשה ועשרים יצילו שנים ועשרה יצילו אחד ולא בקש על פחות מעשרה שדור המבול היו שמנה צדיקים ולא הצילו על דורן ותשעה על ידי צירוף כבר ביקש ולא מצא כל אלו דברי הרב ז"ל ואני תמה אם כן מה התפלה והתחינה הזאת אשר היה מתחנן בכל פעם ופעם "אל נא יחר לאדני" ו "הנה נא הואלתי" והלא ראוי הוא שיהיו ארבעים מצילין ארבעה ושלשים והעשרים יצילו לפי חשבון כאשר החמשים יצילו חמש וכן מה שאמר כי תשעה על ידי צירוף כבר בקש ולא מצא והלא לארבעים וחמשה היה מבקש הצירוף ולא היו שם ארבעים וחמשה אבל תשעה אולי ימצאון שם והנה דעת הרב לומר שהרבים ראוין להצלה גדולה יותר מאשר יצילו המועטים אפילו הצלה מועטת כמו שאמרו (ת"כ בחקותי) אינו דומה מועטין העושין את התורה למרובים העושין את התורה והנה הודה הקב"ה שיצילו ארבעים וחמשה בצירוף צדיקו של עולם כל הכרכין כאילו היו חמשים שלמין ומעתה כשיהיו מ' צדיקים מצילין ארבעה אף בצירוף הצדיק יתעלה ינצלו וכן השלשים והעשרים והעשרה שכבר הודה בצירוף הזה ואם תאמר שהודה בו עם ארבעים וחמשה שהם רבים ושמא לא יודה בצירוף עם המועטין כמו שאמרנו צדקת ה' ראויה היא להצטרף ולהציל כיון שהודה שלא יבדיל בין רב למעט זה דעת הרב ודרך פשט הכתובים סלולה שאמר תחילה חמשים לתת חשבון שלם של עשרה לכל אחד ואחד וחזר ופחת כמו שיכול ולהציל הכל היה אומר ולא ידעתי מי הכניסו לרב במה שאמר
@26 **בתוך העיר** . פירש רבי אברהם שיהיו יראים את השם בפרהסיא וכן שוטטו בחוצות ירושלם (ירמיהו ה א) והנכון בעיני כי אברהם אמר "בתוך העיר" לאמר שאפילו יהיו נכרים בתוכה ראוי שיצילוה ואמר זה בעבור לוט וחשב אולי יש אחרים שם
@28 **לא אשחית אם אמצא שם** . יבטיח אותו שלא ישחית אם ימצאון שם כן ולא היה אומר לו "דע שאין שם כמספר הזה שאמרת" לפי שעדיין לא נגמר דינם כאשר אמר ארדה נא ואראה והנה אברהם לא ידע מה יעשה בהם ולכן השכים בבקר והשקיף על פני סדום ובראותו כי נשחתו ידע שלא היו שם כן
@35 **הנה נא אדוני** . לשון רש"י הנה נא אתם אדונים לי אחר שעברתם עלי והנכון שהוא לשון תחינה אדני הנה נא בית עבדכם סורו נא אלי ומלת "סורו" כמו סורה שבה פה (רות ד א) סורה אדני סורה אלי אל תירא (שופטים ד יח) וטעם והשכמתם והלכתם לדרככם להגיד להם שלא יתעכבו בעיר אחר הבקר כי ידע בענין אנשי העיר ורשעם אבל היה חושב כי באור הבקר יעשוה או שראה אותם כהולכי ארחות לא יתעכבו בעיר ואמר והשכמתם והלכתם לדרככם אם תרצו
@36 **ויפצר בם מאד** . היה ללוט זכות בהפצירו בהם והיה לו חפץ טוב בהכנסת אורחים והיו ממאנים כדי לזכותו ולכן שמעו לו בסוף כי מתחלה לא היו רוצים לבא לביתו כי אינו צדיק תמים ורבותינו אמרו (ב"מ פז) מסרבין לקטן ואין מסרבין לגדול ואם כן יהיה כדרך מוסר בני אדם
@38 **ונדעה אותם** . כוונתם לכלות את הרגל מביניהם כדברי רבותינו (סנהדרין קט) כי חשבו שבעבור טובת ארצם שהיא כגן ה' יבאו שם רבים והם היו מואסי הצדקה אבל לוט בעשרו וממונו בא אליהם או שבקש מהם רשות או שקבלוהו לכבוד אברהם והכתוב מעיד שזאת כוונתם שנאמר (יחזקאל טז מט) הנה זה היה עון סדום אחותך גאון שבעת לחם ושלות השקט היה לה ולבנותיה ויד עני ואביון לא החזיקה ומה שאמר (לעיל יג יג) רעים וחטאים לה' מאד שהיו מכעיסים ומורדים בשלותם ובענוי האביונים והוא שאמר (יחזקאל טז נ) ותגבהינה ותעשינה תועבה לפני ואסיר אתהן כאשר ראיתי ועל דעת רבותינו (עיין סנהדרין קט) היו בהם כל מדות רעות אבל נגמר דינם על אותו העון מפני שלא החזיקו יד עני ואביון כי היו תדירים באותו עון יותר מכולם וגם כי כל העמים עושים צדקות עם ריעיהם ועם ענייהם לא היה בכל הגוים כסדום לאכזריות ודע כי משפט סדום היה למעלת ארץ ישראל כי היא מכלל נחלת ה' ואינה סובלת אנשי תועבות וכאשר תקיא את הגוי כלו מפני תועבותם הקדימה וקאתה את העם הזה שהיו רעים מכולם לשמים ולבריות ושממו עליהם השמים והארץ והושחתה הארץ בלא רפואה לעולם מפני שבעבור טובה נתגאו וראה הקב"ה שיהיה לאות לבני מרי לישראל העתידים לירשה כאשר התרה בהן גפרית ומלח שרפה כל ארצה כמהפכת סדום ועמורה אדמה וצבויים אשר הפך ה' באפו ובחמתו (דברים כט כב) כי יש באומות רעים וחטאים מאד ולא עשה בהם ככה אבל למעלת הארץ הזאת היה הכל כי שם היכל ה' ועוד אני עתיד לבאר זה בסדר אחרי מות (ויקרא יח כד) אם יחייני הממית והמחיה
@41 **אוציאה נא אתהן אליכם** . מתוך שבחו של האיש הזה באנו לידי גנותו שהיה טורח מאד על אכסניא שלו להציל אותם מפני שבאו בצל קורתו אבל שיפייס אנשי העיר בהפקר בנותיו אין זה כי אם רוע לב שלא היה ענין הזמה בנשים מרוחק בעיניו ולא היה עושה לבנותיו חמס גדול כפי דעתו לכך אמרו רבותינו (תנחומא וירא יב) בנוהג שבעולם אדם מוסר עצמו על בנותיו ועל אשתו והורג או נהרג וזה מוסר בנותיו להתעולל בהן אמר לו הקב"ה לעצמך אתה משמרן והנה לוט היה מתירא עליהם כי היה חושב שהם אנשים אבל כאשר הכו בסנורים את אנשי העיר ואמרו לו כי משחיתים אנחנו את המקום הזה וישלחנו ה' לשחתה אז הכיר בהם והאמין לעשות כל אשר צוו ודע והבן כי ענין פילגש בגבעה (שופטים יט) אף על פי שהוא נדמה לענין הזה איננו כמוהו לרוע כי הרשעים ההם לא היה דעתם לכלות הרגל ממקומם אבל היו שטופי זמה ורצו גם במשכב האיש האורח וכאשר הוציאו אליהם פילגשו נתפייסו בה והאיש הזקן שאמר להם הנה בתי הבתולה ופילגשהו אוציאה נא אותם ועשו להם הטוב בעיניכם (שם יט כד) יודע היה שלא יחפצו בבתו ולא יעשו עמה רעה ועל כן לא אבו לשמוע לו וכאשר הוציא את פילגשו לבדה שתקו ממנו והאיש בעל הבית גם האורח כולם היו חפצים להציל את האיש בפילגשו כי פילגש היתה לא אשת איש וכבר זנתה עליו ובפרץ ההוא עוד לא היו בו כל אנשי העיר כאשר בסדום שנאמר בו "מנער ועד זקן כל העם מקצה" אבל בגבעה נאמר והנה אנשי העיר "אנשי בני בליעל" (שם יט כב) מקצתם שהיו שרים ותקיפים בעיר כמו שאמר האיש (שם כ ה) ויקומו עלי בעלי הגבעה ועל כן לא מיחו האחרים בידם והנה פנות כל העם מכל שבטי ישראל רצו לעשות גדר גדול בדבר להמית אותם שנאמר (שם כ יג) ועתה תנו את האנשים בני בליעל אשר בגבעה ונמיתם ודבר ברור הוא שלא היו חייבין מיתה בדין תורה שלא עשו מעשה זולתי ענוי הפילגש הזונה ולא נתכוונו למיתה שלה וגם לא מתה בידם וישלחוה מאתם כעלות השחר והלכה מאתם לבית אדוניה ואחר כך מתה אולי נחלשה מרוב הביאות ונתקררה בפתח עד האור ומתה שם אבל מפני שהיו חפצים ואומרים לעשות נבלה כאנשי סדום ראו השבטים לעשות סייג לתורה שלא יעשה ולא יאמר כן בישראל כמו שאמרו ונבערה רעה מישראל (שם) וזה הדין הוא ממה שאמרו רבותינו (סנהדרין מו) בית דין מכין ועונשין שלא מן התורה ולא לעבור על דברי תורה אלא לעשות סייג לתורה ושבט בנימין לא הסכימו בדבר זה שלא היה בהם חיוב מיתה בענוי הפלגש ואולי הקפידו עוד בני בנימין על אשר לא שלחו להם מתחילה ועשו ההסכמה שלא מדעתם ולפי דעתי שזה ענשם של ישראל להנגף בתחילה מפני שלא היתה המלחמה נעשית מן הדין והגדר עצמו על שבט בנימין היה מוטל לעשותו ולא עליהם שמצוה על השבט לדון את שבטו (ספרי קמד) והנה שתי הכתות ראויות להענש כי בנימין מרשיע שאינו חושש ליסר הרעים ולא לגעור בהם כלל וישראל עושין מלחמה שלא מן הדין וגם את פי ה' לא שאלו בזה אבל אמרו מי יעלה לנו בתחלה למלחמה על בני בנימין (שופטים כ יח) כי מעצמם הסכימו למלחמה על כל פנים וכן לא שאלו בענין הנצוח "אם תתנם בידי" כי בטחו בזרוע בשר שהיו רבים מאד כי עתה כמוהם עשרה פעמים ויותר ולא שאלו אלא "מי יעלה לנו בתחלה" והוא כמו גורל ביניהם אולי היה כל שבט אומר "לא אעלה אני תחלה" או אומר "אני ראשון" והקב"ה השיב כפי שאלתם יהודה בתחלה לאמור כי יהודה הוא בראש לעולם כי ביהודה בחר ה' לנגיד (דהי"א כח ד) ולכך לא אמר "יהודה יעלה" כשאר המקומות (עיין שופטים א ב) כי לא הרשה אותם אבל לא מנעם ולא אמר להם "לא תעלו ולא תלחמו" מפני ענשו של בנימין והנה הלך השם עם שניהם בקרי והניחם למקרים ובני בנימין היו גבורים ועריהם בצורות והשחיתו בישראל הבוטחים בזרוע בשר והוסיפו עונש על ענשם כי די היה להם להבריח ישראל מן הגבעה והם הכו בהם למשחית איבת עולם והפילו מהם עם רב ועצום כ"ב אלפים והנה ישראל כאשר הכו מכה רבה נודעה להם שגגתם כי עשו מלחמה עם אחיהם שלא ברשות גבוה ושלא כדין תורה ועל כן שאלו ביום השני האוסיף לגשת למלחמה עם בני בנימין אחי (שם כ כג) והזכירו עתה האחוה לשאול אם הוא אוסר עליהם המלחמה והשם הרשה אותם עתה ביום השני ואמר עלו אליו כי עתה מותר להם לדרוש דם אחיהם השפוך והם לא שאלו הנצוח כי עדיין היו בוטחים ברובם לנצח על כל פנים והשם לא באר להם רק כי המלחמה מותרת להם ומפני שעדיין לא נתכפר ענשם הראשון נפלו מהם גם ביום השני י"ח אלפים וביום השלישי גזרו תענית ויצומו ויבכו לפני ה' והקריבו עולות לכפר על הרהורי הלב אשר בטחו בזרועם והקריבו שלמים והם שלמי תודה כי ראו עצמם כאלו כלם פלטים מחרב בנימין וזה משפט כל הנמלטים להקריב תודה כענין שנאמר (תהלים קז כב) ויזבחו זבחי תודה ויספרו מעשיו ברנה וכתוב (שם כז ו) ועתה ירום ראשי על אויבי סביבותי ואזבחה באהלו זבחי תרועה אשירה ואזמרה לה' והנה היו בשני הימים המתים מישראל ארבעים אלף ומבנימן נפלו בסוף כ"ה אלפים אנשי חיל (שופטים כ לה) ומעיר מתום עד כל הנמצא (שם כ מח) רבים ויתכן שיהיו ט"ו אלפים בין אנשים ונשים והטף והיה עונש שתי הכתות בשוה ומה נכבדו דברי רבותינו (סנהדרין קג) שהיה הקצף בפסלו של מיכה אמר הקב"ה בכבודי לא מחיתם בכבוד בשר ודם מחיתם לומר בכבודי לא מחיתם במחוייבי מיתה ופושטים ידיהם בעיקר בכבוד בשר ודם מחיתם יותר משורת הדין ועל כן סכל עצת שתי הכתות ואמץ את לבבם ולא זכרו ברית אחים ואחר המעשה נתחרטו כמו שנאמר (שופטים כא ב) ויבא העם בית אל וישבו שם עד הערב לפני האלהים ויבכו בכי גדול ויאמרו למה ה' אלהי ישראל היתה זאת בישראל להפקד היום מישראל שבט אחד כי הכירו טעותם וענשם והנה בדרך גררא פירשנו ענין מהותם ואינו מבואר והזכרנו סיבותיו
@42 **ויפצרו באיש בלוט** . לא מצאתי המלה הזאת רק בדברי הפיוסים אם כן נפרש זה שפייסו ממנו הרבה שיפתח להם הדלת וכאשר לא רצה לעשות כן נגשו לשבור אותו או שהיה עומד בפני הדלת ולא היה מניחם לקרבה אליו והם פייסו ממנו לסור מפניהם כי לא היו רוצים לפגוע בו וזה טעם גש הלאה שיגש למקום אחר
@45 **חתן ובניך ובנותיך** . לשון רש"י מי משלך עוד בעיר חוץ מאשתך ובנותיך שבבית אם יש לך חתן או בנים ובנות הוצא מן המקום ואם כן יהיה דבורם כדרך בני אדם שהוא לא היה לו בנים כי אם בנות ורבי אברהם אמר חתן ובניך חתנים שהם כבניך ויתכן שהיו לו בנים גדולים נשואי נשים ודיבר עם חתניו תחילה כי היה סבור שבניו ישמעו לו וכאשר צחקו עליו חתניו וארכו הדברים ביניהם השחר עלה והמלאכים לא הניחוהו לקחת רק הנמצאים אתו בבית והנה זכותו של לוט היה מציל בנים ובנות וחתנים לא כאשר חשב אברהם שימית צדיק עם רשע וברור הוא שהיו המלאכים יודעים דעת עליון בזה כי גם צוער בתפלתו נמלטה ויתכן שהיה זה לכבוד האכסניא כי דרך מוסר לשלוחים להציל בעל ביתם וכל אשר לו כאשר עשו שלוחי יהושע (יהושע ו כג) שהצילו גם כל משפחת בעלת ביתם ובבראשית רבה (נ כא) לוט על ידי שכבד את המלאך נשא לו פנים
@49 **ויחזיקו האנשים** . אמר רבי אברהם כי ויחזיקו יבאר שפחד ואין בו כח לברוח והנכון שהוא כמו ותחזק מצרים על העם למהר לשלחם מן הארץ (שמות יב לג) אף כאן היו מושכים בהם בחזקה למהר לשלחם
@49 "בחמלת ה' עליו" - לא בזכותו רק בחמלת האל וברחמיו הרבים או יאמר שהחזיקו בו למהר להוציאם בעוד החמלה עליו פן יצא הקצף מלפני ה' ויספה
@50 **אל תביט אחריך ואל תעמוד בכל הככר** . שיעור הכתוב אל תעמוד בכל הככר ואל תביט אחריך אחר שתנצל כי עד היות לוט בהר לא תרד עליהם רעה ובעבור כן אמר
@50 "ואנכי לא אוכל להמלט ההרה פן תדבקני הרעה" - בהיותי בככר כי אתה לא תאריך לי רק מעט כאשר אמרת מהר המלט ואמר רבי אברהם אל תביט אחריך אתה וכל אשר לך וכן לא תאכל ממנו ומה צורך לזה ואין העונש בכאן מפני שיעברו על אזהרת המלאך אבל הוא הזהירם מדעתו שיגיע להם עונש בהבטה ההיא והוא הזהיר את לוט לזכותו וכל השומע ונזהר הוא את נפשו הציל וענין איסור ההבטה אמר רש"י אתה הרשעת עמהם ובזכות אברהם אתה ניצל אינך רשאי לראות בפורענותן ועוד בו ענין כי הראות באויר הדבר ובכל החליים הנדבקים יזיק מאד וידביקם וכן המחשבה בהם ולכן יסגר האיש המצורע וישב בדד (ויקרא יג מו) וכן נשוכי חיות השוטות ככלב השוטה וזולתו כאשר יראו המים וכל מראה יחזו בהם דמות המזיק וישתטו וימותו כמו שאמרו במסכת יומא (פד) והזכירוהו אנשי הטבע ולכן היתה אשתו של לוט נציב מלח כי באתה המכה במחשבתה כאשר ראתה גפרית ומלח היורד עליהן מן השמים ודבקה בה וקרוב אני לומר כי בהשחית ה' את הערים האלה היה המלאך המשחית עומד בין הארץ ובין השמים נראה בלהב האש כענין במלאך המשחית אשר ראה דוד (דהי"א כא טז) ולכן אסר להן ההבטה ובפרקי דרבי אליעזר (כה) כענין הזה אמרו להם אל תביטו לאחוריכם שהרי ירדה שכינתו של הקב"ה להמטיר על סדום ועל עמורה גפרית ואש עירית אשתו של לוט נכמרו רחמיה על בנותיה הנשואות בסדום והביטה לאחריה לראות אם הולכות הן אחריה וראתה אחורי השכינה ונעשית נציב מלח
@57 **וה' המטיר על סדום** . כתב רש"י בכל מקום שנאמר וה' הוא ובית דינו מאת ה' ולא כתב מאתו דרך מקראות לדבר כן נשי למך (לעיל ד ג) ולא אמר נשי ודוד אמר קחו עמכם מעבדי אדניכם (מלכים א א לג) ולא אמר מעבדי ואחשורוש כתבו בשם המלך (אסתר ח ח) ולא אמר בשמי ואני תמה על הרב ז"ל שכתב מן ההגדות דעות חלוקות ומשוה אותם שזה מחלוקת הוא בבראשית רבה (נא ב) ושם עוד דעת שלישית אבא חלפי ברבי סמקי בשם רבי יהודה ב"ר סימון וה' המטיר על סדום זה גבריאל מאת ה' מן השמים זה הקב"ה אמר רבי אלעזר כל מקום שנאמר וה' הוא ובית דינו אמר רבי יצחק בתורה בנביאים ובכתובים מצינו שההדיוט מזכיר שמו שני פעמים בתורה ויאמר למך לנשיו וגו' הנה אלו שלש מחלוקות בדבר שרבי יהודה ב"ר סימון ייחס השם הראשון לגבריאל שהוא השליח לשחת ונקרא השליח בשם השולח ורבי אלעזר אמר כי הוא ובית דינו הסכימו במשפט ומאתו בא ורבי יצחק אמר שהוא דרך הלשון ואם הבינות מה שכתבתי למעלה תדע כוונתם ב"הוא ובית דינו" ויהיה פשוטו של מקרא ברור לפניך וכן וה' אמר (לעיל יח יז) ושמרו דרך ה' למען הביא ה' שלא אמר שמרו דרכי למען אביא וכן אמר כי גדלה צעקתם את פני ה' וישלחנו ה' וכן ויהי בשחת אלהים וגו' (להלן פסוק כט)
@59 **מאחריו** . מאחרי לוט שהיה הולך אחריהם מאסף לכל ביתו ממהרם להמלט
@62 **ויזכור אלהים את אברהם וישלח את לוט** . ענין הכתוב הזה כי לוט נתחסד עם הצדיק ללכת עמו לשוט בארץ באשר ילך והוא שנאמר (לעיל יב ד) וילך אתו לוט כי לצוות שלו הלך ולכן היה לו זכות להצילו בזכות אברהם כי בעבורו הוא גר בסדום ולולי אברהם עודנו היה בחרן עם מולדתו ולא יתכן שתבא אליו רעה בעבור אברהם שיצא במצות קונו וגם זה היה הענין ששם אברהם נפשו בכפו לרדוף המלכים בעבורו
@63 **כי ירא לשבת בצוער** . כתב רש"י לפי שהיא קרובה לסדום ואינו כן אבל מפני שהיא מן המקומות שנגזרה עליהם ההשחתה ובתחנתו של לוט הניחה המלאך בעבור שלא יוכל להמלט ההרה בו ביום חשב בלבו כי לא יאריך לו עוד אחרי שיש לו זמן רב להמלט ההרה ולכך אמרה בתו ואיש אין בארץ שחשבה כי בצאת אביה משם נשחתה צוער
@64 **ותאמר הבכירה** . אמר רבי אברהם יתכן שהיתה לו אשה אחרת ומתה בתחילה ואין צורך כי "הבכירה" הפך "צעירה" כל גדול באחוה יקרא "בכור" וכל קטן ממנו צעיר לו והפרי הראשון בשנה יקרא "בכורים" וכן בכורי דלים (ישעיהו יד ל) המוקדמים בדלות שהם דלי הדלים וכן בבכורו ייסדנה ובצעירו יציב דלתיה (יהושע ו כו) וכן תרגם אונקלוס רבתא
@65 **וטעם ונחיה מאבינו זרע** . באולי כי אמרו נעשה אנחנו המעשה הראוי לנו כי ירחם האלהים ונוליד זכר ונקבה ויתקיים העולם מהם כי עולם חסד יבנה (תהלים פט ג) ולא לחנם הצילנו ה' והנה היו צנועות ולא רצו לאמר לאביהם שישא אותן כי בן נח מותר בבתו (סנהדרין נח) או שהיה הדבר מכוער מאד בעיני הדורות ההם ולא נעשה כן מעולם וכן רבותינו בהגדות מגנים את לוט מאד (נזיר כג)
@73 **ויאמר אברהם אל שרה אשתו אחותי היא** . לא היה זה כמו במצרים כי שם בבואם מצרימה ויראו המצרים את האשה כי יפה היא ויהללו אותה אל השרים ואל המלך כי אנשי זמה הם אבל המלך הזה תם וישר גם אנשיו טובים רק אברהם חשד אותם והיה אומר לכל אחותי היא
@73 "וישלח אבימלך ויקח וגו'" - הנה זה פלא שהיתה שרה אחרי בלותה יפה עד מאד יקחוה המלכים כי בהלקחה אל פרעה אם היתה בת ששים וחמש אפשר שהיה עליה תארה אבל אחרי בלותה וחדל ממנה האורח פלא הוא ואולי חזרה לנערותיה כאשר בישרה המלאך כדברי רבותינו (ב"מ פז)
@83 **וגם אמנה אחותי בת אבי** . לא ידעתי טעם להתנצלות הזה כי גם אם אמת הדבר שהיתה אחותו ואשתו וברצותם באשה אמר להם אחותי היא להטעותם בדבר כבר חטא בהם להביא עליהם חטאה גדולה ואין חילוק והפרש כלל בין שהדבר אמת או שקר ואולי מפני שאמר אבימלך מה ראית כי עשית את הדבר הזה לומר מה ראית בי חטא או רשע שפחדת ועשית כן כי אני לא נסיתי לקחת נשים מבעליהן אז ענה אברהם אני לא ידעתי אתכם אך חשבתי אולי אין יראת אלהים במקום הזה כי רוב מקומות העולם אין בהם יראת אלהים ולכן מעת צאתי מארצי ולכתי בעמים כאיש תועה ולא ידעתי אל איזה מקום נבוא התניתי עמה לאמר כן בכל מקום כי הדבר אמת וחשבתי לי בו הצלת נפש ולא החלותי בדבר בבואי בארצכם כי לא ראיתי בכם עון אשר חטא
@83 "וגם" - אמנה אחותי בת אבי טענה אחרת אמר אני לפי דרכי אמרתי כן שהוא אמת וחשבתי אם אולי יחפצו בה ישאלוני אם היא גם אשתי כיון שלקחוה עבדיך ולא שאלוני דבר אמרתי גם במקום הזה אין יראת אלהים והחרשתי ויתכן שהיה התנאי הזה דברו עמה בבואם במצרים אף על פי שאמר "כאשר התעו אותי אלהים מבית אבי" או שחזר וזרז אותה שם במצרים בשעת מעשה כאשר פירשתי (לעיל יב יא) ודעת רבי אברהם כי כל אלה דברים לדחות את אבימלך
@87 **הנה נתתי אלף כסף לאחיך** . היו הצאן והבקר והעבדים שנתן לו שוים אלף כסף ואמר לשרה הנה נתתי ממון רב לאחיך הנה הכסף לך כסות עיני כל המביטים ביפיך כי את עיניהם ואת ראשיהם החוזים יכסו מהביט בך ומהביט בכל אשר אתך אפילו בנערותיך ושפחותיך והנה לטובתך נתפשת בביתי כי ייראו ממך ויכסו עיניהם מראות בך באמרם המלך פדה נפשו על שלחו יד באשת הנביא והגיד הכתוב שפייס את אברהם בממון ואת שרה בדברים שלא יענש באחד מהם ואמר כי שרה לא נתפייסה לו אבל עם כל זה היתה מתוכחת עמו בטענות לאמר שלא תמחול לו ובשבחה דבר הכתוב ואברהם נתפייס ויתפלל עליו והוא כלשון ועם ישראל יתוכח (מיכה ו ב) אך דרכי אל פניו אוכיח (איוב יג טו) שם ישר נוכח עמו (שם כג ז) ויתכן שיהיה "אלף כסף" אלפי כסף ממון רב כיד המלך וכן הקטן יהיה לאלף (ישעיהו ס כב) לעם רב וכן השיבו נא להם כהיום שדותיהם כרמיהם זיתיהם ובתיהם ומאת הכסף והדגן והתירוש והיצהר אשר אתם נושים בהם (נחמיה ה יא) מאות רבות ממון גדול
@88 **וילדו** . אם הלשון כפשוטו ושב לאשתו ואמהותיו כי עצר ה' בעד רחמם תימה הוא כי נראה כי גם בלילה הראשון אשר לוקחה שרה לבית אבימלך ולא קרב אליה עדיין בא אליו האלהים בחלום ובבקר השכים וקרא לעבדיו גם לאברהם ומתי היה להם עצר רחם אולי היו על פרקן ואחזום חבלי יולדה ולא יכלו להמליט ואולי אברהם איחר תפלתו ימים רבים והנה רפואות אבימלך גם חליו לא נתפרשו ולשון רש"י וילדו ואתרוחו נתפתחו נקביהם והוציאו והוא לידה שלהן בעד כל רחם כנגד כל פתח ואין זה נכון כי אם נאמר ב"וילדו" שהוא יציאת החוץ שמצינו לידה בענינים רבים כגון הרה עמל וילד שקר (תהלים ז טו) לדת חק (צפניה ב ב) מה ילד יום (משלי כז א) מה יולידו ויחדשו הימים אבל מלת "רחם" לא תבא על פתח אחר ואין טענה מן בגיחו מרחם יצא (איוב לח ח) שהוא כנוי כמו בטן האדמה (שם א כא) ודעת אונקלוס איננה כדברי הרב כי הוא שתרגם "ואתרוחו" עשה "רחם" כפשוטו "פתח ולדא" אלא שרצה לכלול גם אבימלך במלת וילדו ולשון בראשית רבה (נב יג) כי עצור עצר ה' עצירה בפה עצירה בגרון עצירה בעין עצירה באוזן עצירה מלמעלה עצירה מלמטה והמדרש הזה להם מיתור לשון הכפל עצור עצר לא שיפרשו כל רחם כל נקב והנכון בעיני כי מיום אשר נלקחה שרה לקה אבימלך באברי התשמיש ולא יוכל לשמש וזהו לא נתתיך לנגוע אליה כי הנגיעה והקריבה בנשים הוא על התשמיש כענין אל תגשו אל אשה (שמות יט טו) ואקרב אל הנביאה (ישעיהו ח ג) ואשתו ואמהותיו שהן מעוברות עצר בעד רחמן ולא יכלו להמליט כי "עצירת רחם" הוא שלא תהר כדרך וה' סגר רחמה (שמואל א א ה) אבל "עצירה בעד הרחם" הוא שלא תלד כלשון גדר בעדי ולא אצא (איכה ג ז) ועמדה שרה בביתו ימים ולא שב אבימלך מדרכו הרעה כי לא הבין עד שבא אליו האלהים בחלום והודיעו ולא פירש הכתוב חולי אבימלך והזכירו ברמז דרך מוסר וכבוד לשרה ואחרי תפלת אברהם נרפא אבימלך ואשתו ואמהותיו וילדו הנשים
@90 **וה' פקד את שרה כאשר אמר** . בהריון כאשר דבר בלידה לשון רש"י ואין "פקידה" אלא לשון זכירה והשגחה על הנפקד כגון פקוד יפקוד אלהים אתכם (להלן נ כה) פקוד פקדתי אתכם ואת העשוי לכם (שמות ג טז) ויפקוד שמשון את אשתו בגדי עזים (שופטים טו א) אף כאן וה' פקד את שרה זכר את שרה ועשה לה כאשר דבר וכן הלשון בכל העקרות היולדות ברחל ויזכור אלהים את רחל (להלן ל כב) ובחנה ויזכרה (אלהים) ה' (שמואל א א יט) וכך אמרו פקדונות הרי הן כזכרונות (ר"ה לב)
@96 **מי מלל לאברהם** . לשון שבח וחשיבות הוא ראו מי הוא וכמה הוא גדול ושומר הבטחתו ומבטיח ועושה לשון רש"י ולא מצינו מלת "מי" בערך כזה למעלה וכבוד רק לבזיון מי אבימלך ומי שכם (שופטים ט כח) מי דוד ומי בן ישי (שמואל א כה י) והנכון בעיני כי אמרה צחוק עשה לי אלהים כל השומע יצחק לי למלאת פיו ברנה ושחוק בפלא הנעשה לי כי מי בכל השומעים שאמר לאברהם מתחלה תניק בנים שרה אין בעולם שיאמר אליו כן אפילו לנחמו כי לא עלה זה על לב איש מעולם ולשון אונקלוס קרוב לזה מאן מהימן דאמר לאברהם וקיים דתוניק בנין שרה כלומר כל השומע יצחק לי כי אין אדם שיהיה נאמן גם בעיני אברהם אם הגיד לו זה הפלא
@98 **מצחק** . לשון עבודה זרה לשון רציחה לשון גלוי עריות מריב עם יצחק על הירושה ואומר אני בכור ויורש פי שנים ויוצאין לשדה ונוטל קשתו ויורה בו חצים כמה דתימר כמתלהלה היורה זיקים חצים ומות כן איש רמה את רעהו ואמר הלא משחק אני (משלי כו יח) ומתשובת שרה אתה למד כי לא יירש בן האמה הזאת וגו' כל זה לשון רש"י ואף כאן הרב כותב המחלוקות כולם דתניא (תוספתא סוטה פ"ו ה"ג) אמר רבי שמעון בן אלעזר אצלנו הגירסא בן יוחאי ד' דברים היה רבי עקיבא דורש ואיני דורש כמותו ונראין דברי מדבריו דרש רבי עקיבא ותרא שרה את בן הגר המצרית אשר ילדה לאברהם מצחק אין צחוק אלא לשון עבודה זרה וכו' ואני אומר חס ושלום שיהא בביתו של צדיק כך איפשר מי שכתוב בו כי ידעתיו למען אשר יצוה את בניו ואת ביתו וגו' (לעיל יח יט) יהא בביתו עבודה זרה וגלוי עריות ושפיכת דמים אלא אין צחוק האמור כאן אלא לשון ירושה שמשעה שנולד יצחק היו הכל שמחין אמר להם ישמעאל שוטים אני בכור ואני נוטל פי שנים שמתשובה שאמרה שרה אמנו לאברהם אתה למד וכו' ונראין דברי מדבריו וכן הלשון שאמר הרב "מריב עם יצחק על הירושה" אינו נראה נכון שאם כן יהיה זה לאחר ימים רבים ויהיה ישמעאל גדול מאד משאת אותו אמו על שכמה וכן אמרו ז"ל (ילק"ש רמז צה) שהיה בן שבע עשרה שנה אם כן היה בשנה שנגמל יצחק ורבי אברהם אמר על דרך הפשט כי מצחק משתעשע כדרך כל נער ותקנא בו בעבור היותו גדול מבנה והנכון בעיני שהיה זה ביום הגמל את יצחק וראתה אותו מלעיג על יצחק או על המשתה הגדול ולכך אמר הכתוב "את בן הגר המצרית" ולא אמר "את ישמעאל" מצחק וכן אמרה
@98 "גרש את האמה הזאת ואת בנה" - כי אמרה העבד המלעיג על אדוניו חייב הוא למות או להלקותו ואיני רוצה רק שתגרש אותו מאתי ולא יירש בנכסיך כלל עם בני שהוא בן גבירה ואמרה שיגרש גם אמו כי לא יוכל הנער לעזוב את אמו ועזב את אמו ומת
@100 **על אודות בנו** . שיצא לתרבות רעה ופשוטו על שאומרת לו לשלחו זה לשון רש"י והנכון בעיני כי הכתוב סיפר בכבוד אברהם ואמר שלא היה הדבר רע מאד בעיניו מפני חשק פילגשו וחפצו בה ואלו אמרה לו שתגרש האמה בלבד היה עושה כרצון שרה אבל מפני בנו חרה לו מאד ולא רצה לשמוע אליה והקב"ה אמר לו שלא ירע בעיניו על הנער ולא על האמה כלל וישמע לקול שרה כי ביצחק לבדו יקרא לו שמו וישמעאל לא יקרא לו זרע ומפני שהיה אברהם מפחד עליו שלא יקראנו אסון בשלחו אותו ממנו אמר כי ישימנו לו לגוי ויברכנו מפני שהוא זרעו באמת
@103 **ואת הילד וישלחה** . נמשך למעלה ויתן אל הגר ואת הילד כי גם הילד נתן לה שילך עמה באשר תלך
@104 **ותשלך את הילד** . גברה עליו הצמאה ולא יכול ללכת והשכיבתו אמו תחת האילן מושלך ונעזב או כענין וישליכם אל ארץ אחרת (דברים כט כז) אל תשליכני מלפניך (תהלים נא יג) ענין שלוח ורבי אברהם אמר ותשלך כי לקחתו בחיקה בעת שנחלש בצמא ורבותינו אמרו (ב"ר נג יג) שהיה חולה בעת ששלחו ושם על שכמה את הילד וזה הטעם "ותשלך" והיה כל הענין הזה לאברהם מפני שצווה לעשות ככל אשר תאמר שרה והיא צותה להוציאו מיד ובמצותה לא נתן להם כסף וזהב ועבדים וגמלים נושאים אותם
@106 **באשר הוא שם** . לפי מעשים שהוא עושה עכשיו הוא נדון ולא לפי מעשים שהוא עתיד לעשות לפי שהיו מלאכי השרת מקטרגין וכו' לשון רבינו שלמה מדברי רבותינו והנכון בעיני בדרך הפשט שיאמר כי שמע אלהים אל קול הנער במקום אשר הוא שם הודיע אותה שלא תצטרך ללכת משם אל מעין ובור כי במקום ההוא ירוה צמאו מיד ואמר לה קומי שאי את הנער אחרי שתותו כי לגוי גדול אשימנו וכמוהו באשר כרע שם נפל שדוד (שופטים ה כז) ובאשר חללים שם הוא (איוב לט ל) ירמוז למקום
@109 **רובה קשת** . בעבור היות קשת תואר אמרו כי "רובה" הוא המורה החצים מלשון יסבו עלי רביו (איוב טז יג) וימררוהו ורבו (להלן מט כג) ו "קשת" הוא העושה הקשתות ויותר נכון ש "רובה" הוא המורה ויאמר על המורה החצים ועל משליך האבנים וזולתם כאשר יאמר אשר יריתי ביני וביניך (להלן לא נא) ולכן יתאר אותו פעם אחרת כי הוא קשת וכן וימצאוהו המורים אנשים בקשת (שמואל א לא ג)
@112 **השבעה לי באלהים הנה אם תשקור לי** . מלת "אם" בכל מקום מספקת אל תחשוב בה בלתי זה והיא באה ברוב מקומות השבועה אם תשקור לי לכן נשבעתי לבית עלי אם יתכפר עון בית עלי (שמואל א ג יד) אחת נשבעתי בקדשי אם לדוד אכזב (תהלים פט לו) אם יבואון אל מנוחתי (שם צה יא) ויקצוף וישבע לאמר אם יראה איש באנשים האלה (דברים א לד לה) והענין כי בעבור היות השבועות באלה יאמר השבעה לי לאמר כה יעשה לי אלהים וכה יוסיף אם תשקור לי וכן אמר (להלן כו כח) תהי נא אלה בינותינו ובענין הגבוה נשבעתי בקדשי אם לדוד אכזב (תהלים פט לו) ואם יתכפר עון בית עלי (שמואל א ג יד) כלומר אם יהיה כן אין דברי אמת וכיוצא בזה שלא ירצה לפרש התנאי והכתוב יכנה ויקצר בהן וכמותם בחסרון התנאי (דהי"א ד י) ויקרא יעבץ לאלהי ישראל לאמר אם ברך תברכני והרבית את גבולי וגו' ועשית מרעה לבלתי עצבי ויבא אלהים את אשר שאל יחסר התנאי כולו וכן אם יראו את הארץ (במדבר יד כג) יחזור לפסוק ראשון חי אני וימלא כבוד ה' את כל הארץ ויקצר השבועה ולשון תשקור לי בעבור היותו מלך והוא גר בארצו או שיהיה משקר באהבתו כי אוהב נאמן היה לו לכבדו ולעשות כרצונו הלא תראה שלא מצא בו דבר זולתי באר המים אשר גזלו עבדיו והוא אומר לו כחסד אשר עשיתי עמך
@121 **וישובו אל ארץ פלשתים** . ענינו וישובו אל עירם אשר בארץ פלשתים כי בארץ פלשתים היו אבל הם יושבים בגרר שהיא מדינת המלך והוא יושב בבאר שבע שהיא בארץ פלשתים בנחל גרר
@122 **ויקרא שם בשם ה' אל עולם** . פי' הכתוב שקרא בשם ה' המנהיג בכחו הזמן או שיקראו השמים והארץ "עולם" כלשון הבא תמיד בדברי רבותינו והודיע בזה שקרא אברהם והודיע לבריות סוד הנהגת העולם בכללו שהוא בשם ה' החסין בכח שיש לו אילות בכולם הרב אמר במורה הנבוכים (ב יג) שהוא רומז לקדמות האל כי הודיע היותו קודם לזמן אבל אונקלוס אמר ב "ויקרא" שהוא תפלה
@124 **והאלהים נסה את אברהם** . ענין הנסיון הוא לדעתי בעבור היות מעשה האדם רשות מוחלטת בידו אם ירצה יעשה ואם לא ירצה לא יעשה יקרא "נסיון" מצד המנוסה אבל המנסה יתברך יצוה בו להוציא הדבר מן הכח אל הפועל להיות לו שכר מעשה טוב לא שכר לב טוב בלבד דע כי השם צדיק יבחן (תהלים יא ה) כשהוא יודע בצדיק שיעשה רצונו וחפץ להצדיקו יצוה אותו בנסיון ולא יבחן את הרשעים אשר לא ישמעו והנה כל הנסיונות שבתורה לטובת המנוסה
@125 **קח נא את בנך את יחידך** . בעבור היותו בן הגבירה והוא לבדו אשר יקרא לו זרע קראו יחידו ובא הלשון להגדיל המצוה אמר קח נא את בנך היחיד האהוב יצחק והעלהו עולה לפני
@125 "המוריה" - לשון רש"י היא ירושלים וכן בדברי הימים (ב ג א) לבנות את בית ה' בירושלים בהר המוריה ורבותינו פירשו (תענית טז) שמשם יצאה הוראה לעולם ואונקלוס תרגמו על שם הקטורת שיש בו מור וסמים ואם כן יהיה פירושו אל הארץ אשר תהיה מוריה או שנקראת כן מעולם על שם העתיד ובבראשית רבה (נה ז) כך אמרו רבנין אמרין למקום שהקטורת קרבה כמה דתימר אלך לי אל הר המור (שיר השירים ד ו) אבל דעת אונקלוס שאמר "ארעא פולחנא" אינו נראה כן על המור שבקטורת שאין לשון "פולחנא" על סם אחד מסמי אחת העבודות ולמה לא אמר "לארעא דקטורת בוסמין" אבל דעתו לומר בארץ אשר יעבדו שם האלהים ויתכוין בזה למה שדרשו בפירקי רבי אליעזר (לא) אמרו באצבע הראה הקדוש ברוך הוא לאברהם אבינו את המזבח אמר לו זהו המזבח הוא המזבח שהיה אדם הראשון מקריב בו הוא המזבח שהקריבו בו קין והבל הוא המזבח שהקריבו בו נח ובניו שנאמר ויבן שם אברהם את המזבח מזבח אין כתוב כאן אלא "המזבח" הוא המזבח שהקריבו בו הראשונים עד כאן ושם "מוריה" עשאו מן מורא ששם יראו האלהים ועבדו לפניו והנכון על דרך הפשט שהוא כמו אל הר המור ואל גבעת הלבונה כי ימצאון שם בהר ההוא מור ואהלים וקנמון כענין שאמרו (ירושלמי פאה ז ג) קנמון היה גדל בארץ ישראל והיו עזים וצבאים אוכלים ממנו או שנקרא כן לשבח ישראל והנה בכאן קורא שם הארץ "ארץ מוריה" ושם (דהי"ב ג א) נראה כי הר הבית לבדו יקרא "הר המוריה" ואולי נקראת העיר על שם ההר ההוא אשר בתוכה הארץ אשר בה המוריה וההר לבדו הוא נקרא מוריה ואברהם ידע את הארץ ולא ידע את ההר ולכן אמר לו שילך אל ארץ המוריה והוא יראנו אחד ההרים ששם שנקרא ככה וצוהו להעלותו במקום ההוא כי הוא ההר חמד אלהים לשבתו ורצה שתהיה זכות העקידה בקרבנות לעולם כאשר אמר אברהם "ה' יראה" ועוד כי למען צדקו הגדיל טרחו ורצה שיעשה זה אחרי מהלך שלשה ימים כי אלו יעשה כן בפתע פתאום במקומו היתה פעולתו במהירות ובהלה אבל כשיהיה אחר מהלך ימים כבר נעשה בישוב דעת ועצה וכך אמרו בבראשית רבה (נה ו) רבי עקיבא אומר נסה אותו בוודאי שלא יהיו אומרין הממו וערבבו ולא היה יודע מה לעשות
@126 **ויבקע עצי עולה** . זריזותו במצוה אולי לא ימצא שם במקום ההוא עצים והוליכם שלשה ימים או שהיה אברהם פוסל לקרבן עץ שנמצא בו תולעת כדין התורה (מדות ב ה) ולקח מביתו עצים טובים לעולה וכן אמר ויבקע עצי עולה
@127 **וירא את המקום מרחוק** . ראה ענן קשור על ההר (ב"ר נו א) ונתקיים בזה אשר אומר אליך ויתכן על דרך הפשט וירא את המקום מרחוק שראה ארץ המוריה כי כל הארץ ההיא היה יודע ויבאו אל המקום אשר אמר לו האלהים עתה הוא הר המוריה שאמר לו "הנה זה ההר אשר אמרתי לך"
@135 **כי עתה ידעתי** . מתחילה היתה יראתו בכח לא יצא לפועל במעשה הגדול הזה ועתה נודעה במעשה והיה זכותו שלם ותהי משכורתו שלימה מעם ה' אלהי ישראל ודעת הפרשה ש"האלהים" הוא המנסה ומצוה בעקידה ו"מלאך ה'" הוא המונע והמבטיח יתברר בפסוק המלאך הגואל אותי (להלן מח טז)
@139 **יען אשר עשית את הדבר הזה** . גם מתחילה (לעיל יג טז טו ה) הבטיחו כי ירבה את זרעו ככוכבי השמים וכעפר הארץ אבל עתה הוסיף לו יען אשר עשית המעשה הגדול הזה שנשבע בשמו הגדול ושיירש זרעו את שער אויביו והנה הובטח שלא יגרום שום חטא שיכלה זרעו או שיפול ביד אויביו ולא יקום והנה זו הבטחה שלימה בגאולה העתידה לנו
@143 **מלכה גם היא** . בעבור היותה בת הרן אחיו היתה בשורה לאברהם שנפקד אחיו הגדול בבנים רבים מבת אחיו המת ומלשון הכתוב נראה שלא ידע באחד מהם בלתי היום ואם היתה פקודתם בימי בחורותם אי אפשר שלא שמעו עד היום כי אין המרחק רב בין ארם נהרים ובין ארץ כנען והנה אברהם בצאתו מחרן בן ע"ה שנה וגם נחור זקן ואשתו איננה בחורה אבל עשה ה' להם נס שנפקדו בימי הזקנה וזה טעם "מלכה גם היא" ובדברי רבותינו (ילק"ש רמז תשסו) יאמר שנפקדה כאחותה
@146 **ובתואל ילד את רבקה** . לא הזכיר הכתוב לבן ואם הוא גדול מרבקה כי לא בא להזכיר רק השמונה שילדה מלכה לנחור אבל הזכיר רבקה כי להודיע יחוסה באה הפרשה וטעם אבי ארם לא הזכיר ארם רק להודיע ולהכיר קמואל כי ארם היה נכבד מאביו ואולי קמואל אחר היה בדורם וזה אבי ארם
@147 **ופילגשו ושמה ראומה** . יספר הכתוב כל הבשורה שבשרו את אברהם בבני אחיו ויתכן שנכתב זה להודיע כל יחוס נחור כי כלם ראויים להדבק בזרעו של אברהם ועל כולם אמר אם לא אל בית אבי תלך ואל משפחתי (להלן כד לח) חסלת פרשת וירא
